INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (169, 6, 11, '2', NULL, NULL, 'The planned maintenance system (PMS) was not available onboard at the time of our survey; it was provided later after we had disembarked from the vessel. The PMS document included reminders for pending items. The reminders in the PMS for pending items refer to the due date of next inspection.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
