INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (541, 31, 1, '2', NULL, NULL, 'The Safe Manning Certificate was available in our possession at the time of the survey.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (542, 31, 2, '2', NULL, NULL, 'The crew list is available in our possession with a total crew of 15 people, including the Master. The number of crew onboard complied with the minimum requirement as mentioned in the safe manning certificate.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (543, 31, 3, '2', NULL, NULL, 'The Officer certificates/endorsements were available in our possession at the time of the survey. All the Officer Certificates/Endorsements are valid.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (544, 31, 4, '2', NULL, NULL, 'The class certificates for hull and machinery, including the load line, were maintained and up to date. The statutory certificates were also maintained and up to date.  Several ship certificates will due within the next 3 months as the following: - Cargo Ship Construction Certificate will be expired on 13 July 2024. - Cargo Ship Safety Certificate will be expired on 13 July 2024. - Cargo Ship Radio Certificate will be expired on 13 July 2024. - Safe Manning Document will be expired on 26 September 2024. - National Pollution Prevention Certificate will be expired on 03 October 2024. - National Anti Fouling Certificate will be expired on 13 July 2024.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (545, 31, 5, '2', NULL, NULL, 'The last special survey was carried out on 26 January 2022.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (546, 31, 6, '2', NULL, NULL, 'The last docking survey was carried out on 26 January 2022, concurrently with the class special survey. The docking report is attached to this report.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (547, 31, 7, '2', NULL, NULL, 'No outstanding visa (recommendation) for machinery and hull class certificate exists.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (548, 31, 8, '2', NULL, NULL, 'The Planned Maintenance System (PMS), including the critical equipment list, was available onboard.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (549, 31, 9, '2', NULL, NULL, 'The PMS was available onboard including the spare parts inventory list.  The daily fuel and lube oil consumption was recorded in the engine logbook.  At the time of the survey, the vessel lastly issued the ordering list addressed to the shore office at several times.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (550, 31, 10, '1', NULL, NULL, 'The Planned Maintenance System (PMS) was available onboard but not completed with the overdue maintenance record, as the vessel has just been handed over to the new owner.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (551, 31, 11, '1', NULL, NULL, 'The Planned Maintenance System (PMS) was available onboard but not completed with the remainder of the pending items, as the vessel has just been handed over to the new owner.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (552, 31, 12, '2', NULL, NULL, 'The vessel''s draught was measured and recorded in the deck logbook.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (553, 31, 13, '2', NULL, NULL, 'The last page of the logbook was left empty by the crew.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (554, 31, 14, '1', NULL, NULL, 'The stability booklet was not available onboard.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (555, 31, 15, '6', NULL, NULL, 'The guidelines on the stowage plan were unavailable for our inspection due to the type of the vessel being general cargo.  The cargo securing book approved by the class is not available onboard.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (556, 31, 16, '2', NULL, NULL, 'The UTM report was made available after we disembarked from the vessel. The vessel''s steel structures'' diminution level is still below the class maximum allowable limit of 20%.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (557, 31, 17, '2', NULL, NULL, 'At the time of our survey, the vessel was berthed on the port side position at Agats Port. As far as could be ascertained, the port side shell plating from aft to fore-ends, from the sheer down to the waterline, was visually found to be in fair condition, with fair painting work and light indentations observed at places.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (558, 31, 23, '2', NULL, NULL, 'The deck plating on the forecastle, main, and poop deck were found in fair condition and well painted.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (559, 31, 24, '2', NULL, NULL, 'The port side draft marks/load lines were clearly marked and visible.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (560, 31, 25, '2', NULL, NULL, 'The draft marks/load lines were measured correctly.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (561, 31, 26, '1', NULL, NULL, 'The starboard side stairway on the main deck leading to the poop deck was found chipped and corroded.  Meanwhile the other guardrails, walkways, and ladders located in the forecastle deck, main deck, poop deck, and accommodation deck were found in fair condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (562, 31, 27, '2', NULL, NULL, 'Generally, the windlass and winches structures were found in fair condition and in order.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (563, 31, 28, '3', NULL, NULL, 'The mooring ropes and wire were in good order.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (564, 31, 29, '2', NULL, NULL, 'The mooring work areas were non-slippery and orderly.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (565, 31, 30, '5', NULL, NULL, 'The ballast tank inspection could not be conducted since the manhole located on the tank top was covered by the remaining cargo at the time of our survey.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (566, 31, 31, '5', NULL, NULL, 'The ballast tank inspection could not be conducted since the manhole located on the tank top was covered by the remaining cargo at the time of our survey.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (567, 31, 32, '2', NULL, NULL, 'The gangway, including the pilot ladder and access ladder, was found in fair condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (568, 31, 33, '6', NULL, NULL, 'The vessel was not applicable with the cargo crane.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (569, 31, 34, '1', NULL, NULL, 'Generally, most mooring equipment (bollard, fairlead, roller, capstan) was not clearly marked with Safe Working Load (SWL) information. Several fairleads at aft were found chipped.  Meanwhile, structurally, the mooring equipment was found in fair condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (570, 31, 35, '1', NULL, NULL, 'Most air vents or sounding pipes were not clearly marked with the compartment they served, while structurally were found in satisfactory condition.  The air vents were not provided with floaters.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (571, 31, 36, '2', NULL, NULL, '14,352 hours', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (572, 31, 37, '2', NULL, NULL, 'The Main Engine routine maintenance for the engine piston ring, connecting rod and injector replacement was performed in April 2021.  The maintenance records follow the engine maker manual, which is attached.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (573, 31, 38, '2', NULL, NULL, 'The Main Engine coundition was found in well maintained without any sign of excessive oil drain sighted.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (574, 31, 39, '2', NULL, NULL, 'AE No. 1 = 7,610 hours AE No. 2 = 9,451 hours', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (575, 31, 40, '2', NULL, NULL, 'The Auxiliary Engine No. 1 was routine maintenance for crank pin, piston ring and nozzle replacement in December 2021, while the Auxiliary Engine No. 2 was routine maintenance for connecting rod, piston ring and nozle replacement in May 2023.   The maintenance records follow the engine maker manual, which is attached.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (576, 31, 41, '3', NULL, NULL, 'The vessel was fitted with 4 (three) auxiliary engines of AE No. 1 and 2 as registered on the class certificate and 2 (two) additional generator sets.  The details of particular engines are below: -	2 (two) engines of AE No. 1 and 2 are located in the engine room,  -	1 (one) engine of Generator Engine is located on the boat deck. -	1 (one) engine of Emergency Generator is located on the boat deck.   All Auxiliary Engines coundition were found in well maintained without any sign of excessive oil drain sighted.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (577, 31, 42, '2', NULL, NULL, 'The calibration result of the Lubrication Oil Pressure sensor was available onboard and recorded in the engine logbook.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (578, 31, 43, '2', NULL, NULL, 'The vessel was provided with the engine equipment manufacturer''s manuals and bulletins.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (579, 31, 44, '2', NULL, NULL, 'The lubricant oil analysis was available onboard.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (580, 31, 45, '2', NULL, NULL, 'The telephony in the engine room was found in order when tested.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (581, 31, 46, '2', NULL, NULL, 'The engine room lighting was found adequate.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (582, 31, 47, '2', NULL, NULL, 'The emergency lighting system in the Engine room was available and in order.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (583, 31, 48, '1', NULL, NULL, 'The engine room was generally wet with oil residue.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (584, 31, 49, '3', NULL, NULL, 'The engine room ventilation was found adequate.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (585, 31, 50, '3', NULL, NULL, 'The thermometer was available in the engine room. The temperature of the engine room is almost similar with the temperature outside the engine room.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (586, 31, 51, '1', NULL, NULL, 'The engine room bilges were found wet with oily water.   Meanwhile, the vessel complied with the ballast management.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (587, 31, 52, '2', NULL, NULL, 'The engine room bilges water level alarm/sensors were in order and found working properly during our test.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (588, 31, 53, '2', NULL, NULL, 'The general condition of the engine room was found in slightly untidy due to the engine crew was still carrying out maintenance on the shaft generator at the time of our survey.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (589, 31, 54, '3', NULL, NULL, 'The compressors were found to be in good condition, while the purifiers were no longer in use on the vessel.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (590, 31, 55, '3', NULL, NULL, 'The engine room pipes, pumps, valves, and coolers were in fair condition without any signs of leakage.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (591, 31, 56, '2', NULL, NULL, 'The engine room pipes were color-coded in accordance with the purpose.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (592, 31, 57, '1', NULL, NULL, 'The engine room floor plate was found oily.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (593, 31, 58, '3', NULL, NULL, 'The main switchboard indicator was in good condition and well-maintained by the crew.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (594, 31, 59, '3', NULL, NULL, 'The engine indicator on the engine was found similar to the ECR.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (595, 31, 60, '1', NULL, NULL, 'The insulation mats were not available on the several switchboard panels.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (596, 31, 61, '3', NULL, NULL, 'The engine room stores were found to be well-stocked and properly arranged.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (597, 31, 62, '3', NULL, NULL, 'The workshop was clean, orderly, and completed with safe working equipment.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (598, 31, 63, '1', NULL, NULL, 'The watertight door leading to the engine room was found corroded on the lower part.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
