INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1113, 80, 173, '2', NULL, NULL, 'The crew list is available in our position with a total crew of 40 persons, including the Master.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1114, 80, 174, '2', NULL, NULL, 'The owner representative only provided the Officer Certificate checklist report instead of the certificate itself. Based on the provided documents, all the Officer certificates and endorsements were valid and complied with operating the vessel within the present trading area.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1115, 80, 175, '2', NULL, NULL, '<div>The class and statutory certificate were maintained and up to date.</div><div>Several certificates were in interim condition and due for next 3 months with the following:</div><div>-  The Passenger Ship Safety Certificate was in interim condition within the due date on 20 March 2024.</div><div>-  The National Anti-Fouling System Certificate was in interim  condition  within  the  due  date  on    19</div><div>December 2023.</div><div>-  The  Shore  Based  Maintenance  Certificate  will</div><div>expire on 25 November 2023.</div><div>-  Rencana Pola Trayek (RPT) Certificate will expire on</div><div>28 January 2024.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1116, 80, 176, '2', NULL, NULL, 'September 2023rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1117, 80, 177, '2', NULL, NULL, '<div>September 2023. The docking report is attached to</div><div>this report.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1118, 80, 178, '1', NULL, NULL, 'No outstanding visa (recommendation) for machinery and hull class certificate exists.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1119, 80, 179, '2', NULL, NULL, 'The  Planned  Maintenance System  includes  critical equipment.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1120, 80, 180, '1', NULL, NULL, '<div>The PMS includes the spare parts inventory list.</div><div>The  daily  fuel  and  lube  oil  consumption  was  not</div><div>recorded in the engine logbook.</div><div>Up  to  the  completion  of  this  report,  the  owner</div><div>representative has not provided us with the ordering list documents (if available) as requested at the time of the survey onboard.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1121, 80, 181, '1', NULL, NULL, 'All the equipment on the PMS was maintained before due time.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
