INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1276, 75, 181, '6', NULL, NULL, '<div>The PMS was regularly updated every month and the</div><div>report was sent directly to the shore office. However, the crew doesn’t know whether there is overdue maintenance or not, since the shore office never giving feedback about it.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
