INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1404, 84, 201, '1', NULL, NULL, '<div>Numbers of sounding pipes on deck were not properly fitted with closing device and some of them cemented.</div><div><br></div><div>Numbers of vent head on deck were found broken. Further, sounding pipe & vent pipe on deck were not clearly marked to the compartment they serve.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1405, 84, 202, '2', NULL, NULL, 'Running hours of ME was not recorded in the logbook', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1406, 84, 203, '2', NULL, NULL, 'rn                                            rn                                            <div><div>The crew advised that</div><div>the main engine was</div><div>lastly maintained in July 2023 for top overhaul.</div></div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1407, 84, 204, '2', NULL, NULL, 'The main engine photographs are attached to this report.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1408, 84, 205, '1', NULL, NULL, '<div>Running hours of the</div><div>AE were not recorded in the logbook. Nonetheless, the crew estimated the running hours of AE No. 1 was around 1,000 hours since the last</div><div>overhaul.</div><div><div>Running hours of</div><div>the AE were not recorded in the logbook. Nonetheless, the crew estimated the running hours of AE No. 2 was around</div><div>900 hours since the last overhaul.</div><div><div>Running hours of AE</div><div>No. 3 was not advised.</div></div></div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1409, 84, 206, '2', NULL, NULL, '<div>The crew advised that</div><div>the auxiliary engine No. 1 was lastly maintained in July</div><div>2023 for top overhaul.</div><div><div>The crew advised</div><div>that the auxiliary engine No. 2 was lastly maintained in July 2023 for top overhaul.</div><div><div>The last maintenance</div><div>of AE No. 3 was not advised.</div></div></div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1410, 84, 207, '2', NULL, NULL, '<div>The auxiliary engine</div><div>photographs are</div><div>attached to this report.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1411, 84, 208, '5', NULL, NULL, '<div>The latest calibration result of lubrication oil pressure sensor</div><div>was not available onboard.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1412, 84, 209, '1', NULL, NULL, '<div>Manufacturer’s manual of the machinery was not provided</div><div>onboard/in the engine room.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1413, 84, 210, '5', NULL, NULL, '<div>The record of lubricants oil analysis of the engines was not</div><div>available onboard for our perusal.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
