INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1415, 84, 212, '2', NULL, NULL, 'The engine room lighting found adequate.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1416, 84, 213, '1', NULL, NULL, '<div>There was no evidence that the emergency lighting in the</div><div>engine room was functional.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1417, 84, 214, '1', NULL, NULL, '<div>The engine room floor plates and ladders were</div><div>oily/slippery.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
