INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1425, 84, 222, '2', NULL, NULL, '<div>The engine room pipes were colored differently with the</div><div>codes they serve.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
