INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1428, 84, 225, '6', NULL, NULL, '<div>The ECR was not equipped with the</div><div>engine indicator/parameter monitoring system. The engine indicator was only available on the control panel of each engine.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1429, 84, 226, '2', NULL, NULL, 'The insulation mats were available.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1430, 84, 227, '2', NULL, NULL, '<div>The engine room stores were found well-stocked and</div><div>properly arranged.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1431, 84, 228, '2', NULL, NULL, 'The workshop was available and found in order.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1432, 84, 229, '1', NULL, NULL, '<div>Watertight door at aft which leading to the engine room</div><div>partly corroded in way of the rubber seal, and the seal</div><div>partly missing.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1433, 84, 230, '2', NULL, NULL, 'The main engine was found in fair condition.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1434, 84, 231, '2', NULL, NULL, 'The exhaust manifolds were covered properly.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1435, 84, 232, '2', NULL, NULL, '<div>The engine manual was not available onboard. Based on</div><div>our perusal of the engine logbook, the operational exhaust gas temperature for each cylinder of the main engine recently ranged between 340 to 360 degrees celsius which was considered as normal temperature by the crew.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1436, 84, 233, '5', NULL, NULL, '<div>The occasion was not ascertained yet since the main</div><div>engine was not running at the time of our survey.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1437, 84, 234, '2', NULL, NULL, 'The auxiliary engines were found in fair condition.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1438, 84, 235, '2', NULL, NULL, 'The exhaust manifolds were covered properly.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1439, 84, 236, '2', NULL, NULL, '<div>The engine manual was not available onboard. The</div><div>exhaust gas temperatures of AE were also not recorded.</div><div>The crew advised that the operational exhaust gas temperature of AE ranged between 210 to 220 degrees Celsius which was considered as normal temperature by the crew.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1440, 84, 237, '2', NULL, NULL, '<div>The auxiliary engine No. 1 and 3 were free from</div><div>significant oil or water leakages. Meanwhile, AE no. 2 was not running at the time of our attendance.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1441, 84, 238, '2', NULL, NULL, 'The inboard stern tube was free from water leakage.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1442, 84, 239, '2', NULL, NULL, '<div>The crew advised that the propeller shaft lastly</div><div>withdrawn, and the stern tube bearings clearance taken/inspected during the last drydock in June 2023. However, the docking report was not available for our perusal.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1443, 84, 240, '5', NULL, NULL, '<div>The propeller condition was not ascertained yet because</div><div>the survey was carried out while the vessel was lying afloat at the anchorage area.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1444, 84, 241, '2', NULL, NULL, 'The emergency steering was in order when tested.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1445, 84, 242, '2', NULL, NULL, '<div>The crew uses HT (Handy Talky) communicate between</div><div>the steering gear room and the bridge.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1446, 84, 243, '2', NULL, NULL, '<div>The emergency steering procedure was available in the</div><div>steering room.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1447, 84, 244, '1', NULL, NULL, '<div>The steering gear synchronization test record was not</div><div>available onboard for our inspection</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1448, 84, 245, '1', NULL, NULL, '<div>There was no evidence that the smoke detector alarm</div><div>was tested.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1449, 84, 246, '2', NULL, NULL, 'The alleyways/stairs were free from obstruction/defect.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
