INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1451, 84, 248, '1', NULL, NULL, 'hose used during fire pump test was leaking.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1452, 84, 249, '2', NULL, NULL, '<div>The crew advised that the AE no. 3 is dedicated as the</div><div>emergency power source/generator, and it was found in order when tested.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1453, 84, 250, '2', NULL, NULL, '<div>The crew advised that the AE no. 3 is dedicated as the</div><div>emergency power source, and it was found in order</div><div>when tested.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1454, 84, 251, '2', NULL, NULL, '<div>The vessel was not equipped with the emergency fire</div><div>pump. Nonetheless, we tested the fire/GS pump, and it was found in order.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1455, 84, 252, '2', NULL, NULL, '<div>The blackout procedure was available and posted</div><div>onboard.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
