INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1540, 85, 197, '5', NULL, NULL, 'The ballast tanks were not accessible at the time of our survey.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1541, 85, 198, '6', NULL, NULL, 'Not Applicablern', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1542, 85, 199, '1', NULL, NULL, '<p>The maintenance record of the derrick cranes was not available.</p><p>The owner was only provided the old certificate. Further, the owners advised that most of the port that the vessel is currently calling do not require these certificate.<br></p><p>rn                                                                                    </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1543, 85, 200, '2', NULL, NULL, 'All deck equipment was found in fair condition.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1544, 85, 201, '1', NULL, NULL, 'Numbers of sounding pipes were not fitted with closing device. Numbers of vent head broken and the pipe found with holes.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1545, 85, 202, '1', NULL, NULL, 'Total running hours of the main engine was not recorded in the logbook', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1546, 85, 203, '2', NULL, NULL, 'The main engine was lastly maintained by replacing the piston ring and cylinder liner in september 2023, based on the crew''s verbal advice', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1547, 85, 204, '2', NULL, NULL, 'The main engine photographs are attached to this report', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1548, 85, 205, '1', NULL, NULL, 'Total running hours of the auxiliary engine was not recorded in the logbook', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1549, 85, 206, '2', NULL, NULL, '<p>The auxiliary engine No. 1 was lastly maintained by replacing the piston ring and cylinder liner on october 2023, based on the crew''s verbal advice. </p><p>The auxiliry engine No. 2 was lastly maintained by replacing the piston ring around June/July 2023, based on the crew''s verbal advice.</p><p>The auxiliry engine No. 3 was last maintained around 2 years ago, and this engine is rarely used by the crew, based on the crew''s verbal advice.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1550, 85, 207, '2', NULL, NULL, 'The auxiliary engine photographs are attached to this report', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1551, 85, 208, '6', NULL, NULL, 'Not Applicable', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
