INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1558, 85, 215, '2', NULL, NULL, 'The engine room ventilation was adequate.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
