INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1572, 85, 229, '1', NULL, NULL, 'Numbers of watertight doors found partly corroded and wasted, particularly in way of the rubber seating. Numbers of access hatches were also found with broken hinges.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1573, 85, 230, '2', NULL, NULL, 'The main engine was found to be in fair condition.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1574, 85, 231, '2', NULL, NULL, 'The hot box and exhaust manifold were covered with lagging.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1575, 85, 232, '2', NULL, NULL, 'The engine manual was not available onboard. Based on our perusal of the engine logbook, the operational exhaust gas temperature for each cylinder of the main engine recently ranged between 300 to 390 degrees celsius which was considered as normal temperature by the crew.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1576, 85, 233, '5', NULL, NULL, 'The occasion was not ascertained yet because the mainengine was not running.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1577, 85, 234, '2', NULL, NULL, 'The vessel was fitted with 3 (three) auxiliary engines inthe engine room. Meanwhile, 1 (one) generator fitted on the poop deck.<br>The crew verbally advised that usually the crew only used two auxiliary engines for operation.<br>The auxiliary engines were found to be in fair condition.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1578, 85, 235, '2', NULL, NULL, 'The hot box and exhaust covers were fitted.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1579, 85, 236, '2', NULL, NULL, 'The engine manual was not  available onboard. The exhaust   gas   temperatures   of   AE   were   also   notrecorded. The crew advised that the operational exhaust gas temperature around 200 degrees Celsius which was considered as normal temperature by the crew.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1580, 85, 237, '2', NULL, NULL, 'The Auxiliary engine No. 2 was running and free from significant oil or  water leakages at the time of our attendance.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1581, 85, 238, '2', NULL, NULL, 'The inboard stern tube was in order and free fromwater leakage.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1582, 85, 239, '2', NULL, NULL, 'The last propeller shaft was withdrawn and the stern tube  bearings  clearance was  taken  on  class  specialsurvey in April 2022.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1583, 85, 240, '2', NULL, NULL, 'The propeller was visually found in fair condition.<br>The vessel was just carried out emergency docking at the time of our attendance due to the CPP system was reportedly leaking, causing the CPP was out of order.<br>After our attendance, the crew advised that the sea trial has been carried out and witnessed by the Harbour Master (Syahbandar) with the satisfactory result.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1584, 85, 241, '2', NULL, NULL, 'The emergency steering is available for our test and was found in good order when tested.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1585, 85, 242, '2', NULL, NULL, 'The crew uses telephony to communicate between thesteering gear room and the bridge.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1586, 85, 243, '2', NULL, NULL, 'The emergency steering procedure was available in the steering room.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1587, 85, 244, '1', NULL, NULL, 'Record for testing the Steering Gear synchronization between the Steering Room and the Navigation Roomwas not available.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1588, 85, 245, '1', NULL, NULL, 'There was no record of the smoke alarm detector test.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1589, 85, 246, '2', NULL, NULL, 'The allaeyways/stairs were free from obstruction/defect', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1590, 85, 247, '1', NULL, NULL, 'The portable fire extinguisher in the engine room was not properly fitted with the hose. Nozzle used during the fire pump test was leaking.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1591, 85, 248, '1', NULL, NULL, 'The fire  hoses used  during the  fire  pump  test  was leaking and the hydrant pipe was also leaking.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1592, 85, 249, '2', NULL, NULL, 'The  emergency  power  sources  were  available  and working properly.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1593, 85, 250, '2', NULL, NULL, 'The additional generator located on poop deck was found in order when tested. The vessel is also equipped with batteries as the emergency power source.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1594, 85, 251, '6', NULL, NULL, 'The vessel is not specifically equipped with the emergency fire pump. However, we tested the general service pump for supplying the water on the hydrants and it was found in order.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1595, 85, 252, '1', NULL, NULL, 'The blackout procedure was not available and posted onboard.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1596, 85, 253, '2', NULL, NULL, 'The portable fire extinguisher is sufficiently providedon each deck of the crew accommodation.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1597, 85, 254, '2', NULL, NULL, 'The  general  alarm  was  found  in  good  order  when tested.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1598, 85, 255, '2', NULL, NULL, 'The escape routes are posted in the crew accommodation', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1599, 85, 256, '2', NULL, NULL, '<p>The emergency light could not be tested  at the time of our attendance since the vessel is supplied by the shotre power during in drydock. The vessel must be blacked out to engage the emergency lighting.</p><p>However the crew verbally advised that the emergency light in the crew accommodation periodically tested and found to be in order. </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1600, 85, 257, '2', NULL, NULL, 'The bridge navigation and communication equipment were working in order when tested.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1601, 85, 258, '2', NULL, NULL, 'A copy of the deviation card for the compass is availableon the bridge. The document is attached to this report.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1602, 85, 259, '2', NULL, NULL, 'The NTM (BPI – Berita Pelaut Indonesia) was availableonboard and updated.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1603, 85, 260, '2', NULL, NULL, 'The   chart   was   recorded,   regularly   updated,   andcovered the ship’s trading area.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1604, 85, 261, '2', NULL, NULL, 'The   vessel   condition   was   verified   and   recorded, including trim, list, draft, and intact stability.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1605, 85, 262, '2', NULL, NULL, 'The crew adequately made and recorded the passage planning during the latest voyages.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1606, 85, 263, '2', NULL, NULL, 'The  stability  calculation  was  available  and  properly recorded.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1607, 85, 264, '1', NULL, NULL, 'The emergency steering procedure was not posted at the bridge deck, even though, the crew was familiar with the emergency steering operation.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1608, 85, 265, '1', NULL, NULL, 'The cargo hold was found in poor condition.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1609, 85, 266, '1', NULL, NULL, 'The cargo hold along with the bilges were filled with waters at the time of our attendance. The crew advised that the rain water ingress to the cargo hold during the vessel in dry dock, added with the leaking tank top.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1610, 85, 267, '1', NULL, NULL, 'The hatch cover was  found with  corroded holes at places.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1611, 85, 268, '2', NULL, NULL, 'The hatch cover panel was found correctly aligned.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1612, 85, 269, '6', NULL, NULL, 'The vessel was not equipped with compression bars, landing pads, and securing devices.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
