INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1817, 83, 231, '2', NULL, NULL, 'The hot box and exhaust manifold were covered properly with lagging.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
