INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1820, 83, 234, '2', NULL, NULL, '<div>The  vessel  was  fitted  with  3  (three)  generator</div><div>engines. However, only 1 (one) auxiliary engine as AE No. 1 registered on the class certificate.</div><div><br></div><div>The details of particular engines are below:</div><div>- 1 (one) engine of AE No. 1, is located in the engine room,</div><div>- 1 (one) engine of generator No. 2 is located in the steering gear room,</div><div>- 1 (one) engine of generator No. 3 is located on the boat deck.</div><div><br></div><div>The crew verbally advised that the engine on the boat deck (Generator No. 3) functioned as an emergency generator.</div><div><br></div><div>Good / Fair / Poor</div><div><br></div><div>Based on the engine logbook, all the auxiliary engines were found in good and satisfactory condition with no abnormality sighted.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1821, 83, 235, '2', NULL, NULL, '<div>The hot box and exhaust manifold were covered</div><div>properly with lagging.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1822, 83, 236, '1', NULL, NULL, 'The exhaust temperatures are never compared with the engine manual book.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1823, 83, 237, '2', NULL, NULL, 'The auxiliary engine free from significant oil or water leakages and/or temporary drainsrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
