INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1825, 83, 239, '2', NULL, NULL, '<div>The last propeller shaft withdrawal was carried out on</div><div>class special survey, and stern tube bearing clearance measurement was taken on March 2023.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
