INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1827, 83, 241, '2', NULL, NULL, '<div>The emergency steering is available for our test and</div><div>was found in good order when tested.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
