INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1874, 88, 132, '5', NULL, NULL, 'The bilge suction test could not be conducted at the time of the survey due to the manhole of the cargo holds bilge was still covered with residue of the remaining cargo.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1875, 88, 133, '2', NULL, NULL, 'The pontoon type of hatch covers, sit on a coaming table without rubber seals and are covered by tarpaulins. The hatch covers generally were in good condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1876, 88, 134, '6', NULL, NULL, NULL, NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1877, 88, 135, '1', NULL, NULL, 'rn                                            The internal structure of ballast tank Nos. 1P and 1S were found generally corroded at places. <span style=', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1878, 88, 136, '2', NULL, NULL, 'rn                                            The ballast tank pressure test was found in order.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1879, 88, 137, '2', NULL, NULL, '<span style=', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1880, 88, 138, '2', NULL, NULL, 'The emergency generator was located on the aft deck and found in order when tested.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1881, 88, 139, '2', NULL, NULL, 'All auxiliary engines are operational.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1882, 88, 140, '1', NULL, NULL, 'The communication with the bridge using the telephone was not functioning at the time of the survey. The crew was using a handy talkie to communicate.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1883, 88, 141, '2', NULL, NULL, '<span style=', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1884, 81, 172, '2', NULL, NULL, '<div>The  Safe  Manning  Certificate  was  available  in  our</div><div>possession soon after we disembarked from the vessel.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1885, 81, 173, '2', NULL, NULL, 'The crew list is available in our possession with a total crew of  14  people, including the Master. The crew amount and rank that was onboard complied with the minimum safe manning requirement.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1886, 81, 174, '2', NULL, NULL, '<div>The Officer certificates/endorsements were available for  our  inspection  at  the  survey.  All  the  Officer</div><div>Certificates/Endorsements are valid.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1887, 81, 175, '2', NULL, NULL, '<div>The class certificates for hull and machinery, including</div><div>the load line, were maintained and up to date. The statutory certificates were also maintained and up to date.</div><div><br></div><div>Several ship certificates will be due within the next 3 months as the following:</div><div>-   Life Raft, Fire Extinguisher, and EEBD Certificate will expire on 15 January 2024.</div><div>-   Sanitation Exemption Certificate will expire on 05</div><div>December 2023.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1888, 81, 176, '2', NULL, NULL, '<div>The last special survey was carried out on 28 August</div><div>2020.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1889, 81, 177, '2', NULL, NULL, '<div>The last docking was carried out on 21 November</div><div>2022. The docking report is attached to this report.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1890, 81, 178, '1', NULL, NULL, 'The latest visa (recommendation) for machinery and hull class certificate has been rectified by the owner and reinspected by the class as stated on the class endorsement certificate. The class was maintained.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1891, 81, 179, '1', NULL, NULL, 'The Planned Maintenance System (PMS), including the critical equipment list, was unavailable onboard.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1892, 81, 180, '1', NULL, NULL, '<div>The PMS was not available onboard. Meanwhile, the</div><div>spare parts inventory was listed separately from the</div><div>PMS.</div><div>The  daily  fuel  and  lube  oil  consumption  was  not</div><div>recorded in the engine logbook.</div><div>At the time of the survey, the Chief Engineer and Master verbally advised that there was no outstanding ordering list.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1893, 81, 181, '5', NULL, NULL, 'The Planned Maintenance System (PMS) was not available onboard. Hence, we could not ascertain the overdue maintenance part.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1894, 81, 182, '1', NULL, NULL, 'The Planned Maintenance System (PMS) was not available onboard. The crew is still composing the PMS.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1895, 81, 183, '2', NULL, NULL, '<div>The vessel''s draught was measured and recorded in</div><div>the deck logbook.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1896, 81, 184, '2', NULL, NULL, 'The last page of the logbook was left empty by the crew.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1897, 81, 185, '2', NULL, NULL, 'The stability booklet was available onboard.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1898, 81, 186, '1', NULL, NULL, '<div>The   guidelines  on   the   stowage  plan   were   not available for our inspection due to the type of the</div><div>vessel being general cargo.</div><div>The cargo securing book approved by the class is not</div><div>available onboard.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1899, 81, 187, '5', NULL, NULL, 'The UTM report was unavailable for our inspection during the survey and has not been provided by the owner up to completion of this report.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1900, 81, 188, '2', NULL, NULL, 'Since the vessel was berthed at the Jetty of Marapokot Port, we could only ascertain the starboard side shell plating and coatings. As far as we could ascertain, the starboard from the fore to the aft shell plating and coating were found in fair condition, with light indentation sighted at places.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1901, 81, 190, '2', NULL, NULL, '<div>The  starboard  draft  marks/load  lines  were  clearly</div><div>marked and visible.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1902, 81, 191, '2', NULL, NULL, 'The draft marks/load lines were measured correctly.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1903, 81, 192, '1', NULL, NULL, 'The starboard railing was found slightly parted. However, the guardrails, walkways, and ladders located in the main deck, poop deck, and accommodation deck were found in fair condition.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1904, 81, 193, '1', NULL, NULL, '<div>Generally, the windlass and winches were found in rusty. In addition, the port winch lock structure was</div><div>found out of the track. The steel structure of the rubber pad seating was found corroded.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1905, 81, 194, '2', NULL, NULL, 'The mooring ropes and wire, including the bridles, were in good order.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1906, 81, 195, '1', NULL, NULL, '<div>At time of our survey, the hydraulic pump pipeline on</div><div>the forecastle deck was discovered to have oil leakage.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1907, 81, 196, '5', NULL, NULL, '<div>The ballast and void tanks were not inspected at our</div><div>survey due to the fill with water to maintain stability during the cargo discharge.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1908, 81, 197, '5', NULL, NULL, '<div>The ballast and void tanks were not inspected at our survey due to filled with water to maintain stability</div><div>during the cargo discharge.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1909, 81, 198, '2', NULL, NULL, 'The gangway, including the accommodation ladder was found in good order.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1910, 81, 199, '5', NULL, NULL, '<div>The 2 (two) cargo cranes were fitted onboard at aft and fore, respectively. However, the maintenance records were not available for our inspection.</div><div>The cargo gear certificate was not available for our inspection.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1911, 81, 200, '1', NULL, NULL, '<div>The fairlead at aft was found detached and missing. Meanwhile,  the  other  steel  structure  of  the  deck</div><div>equipment was found in fair condition, complete with the safe working load information.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1912, 81, 201, '2', NULL, NULL, '<div>The fitted sounding and air vent pipes were clearly</div><div>marked with the compartment they served. The steel structure was found in good condition.</div><div>The air vents were provided with floaters.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1913, 81, 202, '1', NULL, NULL, 'The running hours record of the main engine since the last overhaul has not been handed over from the previous owner. Hence, he has not recorded the present running hours yet. The chief engineer verbally advised that the machinery equipment would conduct a general overhaul on the next docking. rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1914, 81, 203, '1', NULL, NULL, '<p>The main engine was replaced the crankpin and piston ring in August - September 2023. </p><p>The maintenance records followed the engine maker manual. </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1915, 81, 204, '2', NULL, NULL, 'The main engine photographs are attached to this report', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1916, 81, 205, '1', NULL, NULL, '<p>The running hours record of auxilairy engine No. 1 since the last overhaul has not been handed over from the previous owner. Hence, he has not recorded the present running hours yet.</p><p>The running hours record of auxiliary engine No. 2 since the last overhaul has not been handed over from the previous owner. Hence, he has not recorded the present running hours yet.</p><p>The running hours record of auxilary engine No. 3 since the last overhaul has not been handed over from the previous owner. Hence, he has not recorded the present running hours yet.  </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1917, 81, 206, '1', NULL, NULL, '<p>The new ship owner did not receive the previous owner''s last maintenance record of AE No. 1. </p><p>The new ship owner did not receive the previous owner''s last maintenance record of AE No. 2. During our survey, auxiliary engine No. 3 was under overhaul on liner, crankpin, and piston ring replacement.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1918, 81, 207, '2', NULL, NULL, '<p>The auxiliary engine No. 1 engine photogrpahs are attached to this report.</p><p>The auxiliary engine No. 2 engine photographs are attached to this report. </p><p>The auxiliary engine No. 3 engine photographs are attached to this report.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1919, 81, 208, '1', NULL, NULL, 'The calibration result of the Lubrication Oil Pressure sensor was not available onboard.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1920, 81, 209, '2', NULL, NULL, 'The manufacturer''s manuals were available onboard.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1921, 81, 210, '1', NULL, NULL, 'The lubricant oil analysis was not available onboard.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1922, 81, 211, '2', NULL, NULL, 'The telephony in the engine room works appropriately when tested.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1923, 81, 212, '2', NULL, NULL, 'The engine room lighting was found adequate.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1924, 81, 213, '2', NULL, NULL, '<div>The emergency lighting in the engine room was found</div><div>in order when tested.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1925, 81, 214, '2', NULL, NULL, 'The engine room was generally found clean and dry. However, the engine room bilges were found wet.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1926, 81, 215, '2', NULL, NULL, 'The engine room ventilation was found adequate.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1927, 81, 216, '2', NULL, NULL, '<p>rn                                            The thermometer in the engine room was available and located near the engine control room.</p><p> The engine room temperature was found same as the temperature outside the engine room.<br></p><p>                                        </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1928, 81, 217, '1', NULL, NULL, 'The engine room bilges were found wet and dirty. Meanwhile,  the  vessel  complied  with  the  ballast management.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1929, 81, 218, '1', NULL, NULL, 'The engine room bilges alarm was unavailable for our test because the crew was still in the familiarization process with the bilges high-level water alarm system. Hence, we could not ascertain the present or actual condition of the foregoing item.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1930, 81, 219, '2', NULL, NULL, 'The general condition of the engine room was found in good condition.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1931, 81, 220, '2', NULL, NULL, '<div>The   compressors  were   found   in   good   condition.</div><div>However, the purifiers were removed from the vessel.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1932, 81, 221, '2', NULL, NULL, '<div>The engine room pipes, pumps, valves, and coolers were in good order with no leakage sign. However, the</div><div>OWS (Oily Water Separator) was not available for our inspection test since the crew was still in the familiarization process with the foregoing item.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1933, 81, 222, '2', NULL, NULL, 'The engine room pipes were color coded in accordance with the purpose.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1934, 81, 223, '2', NULL, NULL, 'The floor plates and the ladders were found in good condition and free of oil/oily.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1935, 81, 224, '2', NULL, NULL, '<div>The main switchboard indicator was found in good</div><div>condition and well-maintained by the crew.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1936, 81, 225, '2', NULL, NULL, '<div>The  engine  indicator on  the  engine  was  found</div><div>similar to the ECR.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1937, 81, 226, '1', NULL, NULL, '<div>The  insulation  mats  were  found  absent  on  several engine room switchboard panels. In the meantime, the</div><div>insulation mats were available on the engine control room main switchboard panel.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1938, 81, 227, '2', NULL, NULL, '<div>The engine room stores were found well-stocked.</div><div>However, it is not neatly arranged.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1939, 81, 228, '2', NULL, NULL, 'The workshop was clean, orderly, and completed with safe working equipment.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1940, 81, 229, '2', NULL, NULL, 'The watertight doors leading to the engine room were found in fair condition with good rubber sealing.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1941, 81, 230, '2', NULL, NULL, 'Based on the visual inspection and engine logbook on the last voyage, the main engine was found in fair and satisfactory condition with no abnormality sighted.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1942, 81, 231, '2', NULL, NULL, '<div>The  hot  box  and  exhaust  manifold  were  covered</div><div>properly with lagging.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1943, 81, 232, '2', NULL, NULL, '<div>The  exhaust  temperature was  found  in  satisfactory condition, with the evidence not exceeding 5 degrees</div><div>difference compared with the outside temperature.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1944, 81, 233, '5', NULL, NULL, 'The occasion was not ascertained yet because the main engine was not running.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1945, 81, 234, '1', NULL, NULL, 'The auxiliary engine No. 3 was under overhaul on the liner, crankpin, and piston ring. Meanwhile, the auxiliary engines No. 1 and 2 were found in fair and satisfactory condition while running.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1946, 81, 235, '2', NULL, NULL, 'The  hot  box  and  exhaust  manifold  were  covered properly with lagging.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1947, 81, 236, '2', NULL, NULL, 'According to the AE manual, the exhaust temperature was satisfactory.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1948, 81, 237, '5', NULL, NULL, 'AE No. 1 and 2 were freed from significant oil or water leakage. Meanwhile, AE No. 3 was not ascertained yet because the engine was under overhaul.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1949, 81, 238, '2', NULL, NULL, '<div>The inboard stern tube was in good condition and free</div><div>from oil or water leakage.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1950, 81, 239, '1', NULL, NULL, '<div>The owner representative and crew were not advised by the previous owner regarding the last propeller shaft</div><div>withdrawn and the stern tube bearing clearance.</div><div><br></div><div>Based on our inspection of the last docking report, no propulsion system work was carried out in the last docking.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1951, 81, 240, '5', NULL, NULL, 'The propeller condition was not ascertained yet because the survey was carried out while the vessel was berthed at the jetty while carrying out cargo discharge.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1952, 81, 241, '2', NULL, NULL, 'The emergency steering is available for our test and was found in good order when tested.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1953, 81, 242, '2', NULL, NULL, 'The crew uses HT (Handy Talky) and telephony to communicate between the steering gear room and the bridge.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1954, 81, 243, '2', NULL, NULL, 'The emergency steering procedure was available in the steering room.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1955, 81, 244, '5', NULL, NULL, '<div>The steering gear test record was not available onboard</div><div>for our inspection.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1956, 81, 245, '2', NULL, NULL, '<div>The smoke detector alarm test record is not available</div><div>onboard.</div><div>Meanwhile, several smoke detectors were found in</div><div>good order when testing.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1957, 81, 246, '2', NULL, NULL, 'The alleyways/stairs were free from obstruction/defect objects.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1958, 81, 247, '2', NULL, NULL, 'The fire extinguisher and fire hose lockers were found satisfactory condition and stowed adequately with sufficient numbers available onboard.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1959, 81, 248, '2', NULL, NULL, 'The fire main hydrant and hoses were found in good condition with no leakage sign sighted during the test.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1960, 81, 249, '2', NULL, NULL, '<div>The emergency power source and light were available</div><div>and working properly during testing.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1961, 81, 250, '2', NULL, NULL, 'The emergency generator was found in order when testing. The vessel was fitted with one emergency generator located on the engine room''s third floor.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1962, 81, 251, '2', NULL, NULL, 'The emergency fire pump was found in good condition when tested. The Chief Engineer advised that the GS (General Service) and ballast pump could also be an emergency fire pump.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1963, 81, 252, '1', NULL, NULL, 'The blackout procedure was not available and posted onboard.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1964, 81, 253, '2', NULL, NULL, 'The portable fire extinguisher is posted on each accommodation deck and is not overdue for the annual service.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1965, 81, 254, '2', NULL, NULL, 'The general alarm for crew accommodation was found in good condition during testing.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1966, 81, 255, '1', NULL, NULL, '<div>The escape route was not posted with the IMO sign at</div><div>places.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1967, 81, 256, '2', NULL, NULL, '<div>The emergency light in the crew accommodation was</div><div>found in satisfactory condition when tested.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1968, 81, 257, '2', NULL, NULL, '<div>All  the  navigational equipment  was  found  in  order when the flame test was carried out.</div><div>The bridge navigation and communication equipment list is attached to this report.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1969, 81, 258, '2', NULL, NULL, 'A copy of the deviation card for the compass is available on the bridge. The document is attached to this report.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1970, 81, 259, '1', NULL, NULL, '<div>The updated NTM (BPI – Berita Pelaut Indonesia) is unavailable onboard.  The  latest  available NTM  was</div><div>dated May 2023.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1971, 81, 260, '2', NULL, NULL, 'The chart was recorded and updated to comply with the ship''s trading area.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1972, 81, 261, '2', NULL, NULL, 'The   vessel   condition   was   verified   and   recorded, including trim, list, draft, and intact stability.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1973, 81, 262, '2', NULL, NULL, 'The crew adequately made and recorded the passage planning for the first cargo operation voyage from the loading port to the discharging port after the vessel was handed over from the previous owner.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1974, 81, 263, '2', NULL, NULL, 'The C/O made the GM calculation for stability at the time of departure from the loading port.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1975, 81, 264, '2', NULL, NULL, 'The emergency steering procedure was posted on the bridge deck and understood by the crew.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1976, 81, 265, '1', NULL, NULL, 'We could not inspect the full condition of the cargo hold due to still closed with the remaining cargo. As far as could be ascertained, the cargo hold plate was found doubling plate at several places, and cement and epoxy patching were sighted on the cargo hold plate.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1977, 81, 266, '5', NULL, NULL, 'We could not inspect the cargo hold bilges due to still closed by the remaining cargo.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1978, 81, 267, '2', NULL, NULL, 'Structurally,  the  cargo  hatch  covers,  coamings  and access hatches were found in fair condition.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1979, 81, 268, '1', NULL, NULL, 'The hatch cover panel was found correctly aligned and secured.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1980, 81, 269, '2', NULL, NULL, 'The compression bars, landing pads, and securing device were found in good condition, including the fair condition of the rubber seal.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1981, 81, 270, '2', NULL, NULL, 'The internal condition of the cargo space was found clean and dry. However, we could not inspect the tank top due to still closed with the remaining cargo.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1982, 81, 271, '1', NULL, NULL, '<div>We could not inspect the full condition of the cargo hold due to still closed with remaining cargo. As far as could be ascertained, the cargo hold plate was found doubling plate at several places, and cement and epoxy patching were sighted on the cargo hold plate.</div><div><br></div><div>Meanwhile, the steel structure in good condition was also found well coated.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (1983, 81, 272, '2', NULL, NULL, 'According to our visual inspection, the thickness of the hatch covers is still sufficient even though the spot rusted sighted at places.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
