INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2471, 121, 306, '2', NULL, NULL, 'rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            <div>The vessel was fitted with 4 (four) auxiliary engines of AE No. 1, No. 2 and No. 3 and 1 (one) emergency generator sets.</div><div><br></div><div><div>The details of particular engines are below:</div><div><div>- 3 (three) auxiliary engine of AE No. 1, No. 2 and No. 3 are located in the engine room</div><div>- 1 (one) engine of emergency generator is located in the poop deck.</div><div><br></div><div>All auxiliary engines condition were found in well maintained without any sign of leakage. </div></div></div>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
