INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2558, 76, 256, '2', NULL, NULL, 'The crew accomodation deck emergency light system was found in satisfactory condition when tested', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2559, 76, 257, '1', NULL, NULL, 'ECDIS, echosounder, single side band (SSB) and VHF DSC was found out of order', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2560, 76, 258, '2', NULL, NULL, 'Deviation card was available and posted on board', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2561, 76, 259, '1', NULL, NULL, 'Notice to mariner ( NTM), Nautical almanac and tide table were found unavailable onboard', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2562, 76, 260, '1', NULL, NULL, 'Nautical chart were not update. (last 2005)', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2563, 76, 261, '2', NULL, NULL, 'The vessel condition was verified and recorded on deck logbook, including trim, draft and intact stability.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2564, 76, 262, '2', NULL, NULL, 'The passage planning was not recorded by the crew every cargo operating voyage from the loading port yo the discharging port.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2565, 76, 263, '2', NULL, NULL, 'The master made GM calculation for stability at the time of departure from the loading port.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2566, 76, 264, '1', NULL, NULL, 'Emergency steering procedure was not posted at he bridge deck.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2567, 76, 265, '1', NULL, NULL, 'The condition of cargo hold found partly wasted at several places.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2568, 76, 266, '1', NULL, NULL, 'The cargo hold bilges was found filled with water.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2569, 76, 267, '2', NULL, NULL, 'Generally, the hatch cover, coaming were found in fair condition. However, we found the rubber seals on access hatch on cargo hold and void spaces missing.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2570, 76, 268, '2', NULL, NULL, 'The hatch cover panel was correctly aligned and secured', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2571, 76, 269, '1', NULL, NULL, '<p>The hatch cover wa pontoon type, sitting on the coaming table ( landing pads) without a compression bar and sealed by rubber seal due to the vessel carrying the container.</p><p>The condition of securing devices were found broken and corroded at several places. The container landing gear was found indented and parted at the time of our survey.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2572, 76, 270, '2', NULL, NULL, 'Generally, the condition internal of the cargo hold was found in fair condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2573, 76, 271, '1', NULL, NULL, 'The tween deck plate found wasted at several places and the vertical ladder in cargo hold found bent and corroded.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2574, 76, 272, '2', NULL, NULL, 'According to our visual inspection, the thickness of the hatch cover is still sufficient.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2575, 76, 273, '1', NULL, NULL, 'The rubber seal on hatch cover found detached at places.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2576, 76, 274, '2', NULL, NULL, 'The air vents leading to the cargo hold was found in good condtion. However, the air vent not marked with compartment they serve.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2577, 76, 275, '6', NULL, NULL, 'Not Applicable', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2578, 76, 276, '2', NULL, NULL, 'The toe bracket was found in good conditions.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2579, 76, 277, '6', NULL, NULL, 'Not Applicable', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2580, 76, 278, '1', NULL, NULL, 'The suction test on the fore bilges wells was found out of orderduering test.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2581, 76, 279, '2', NULL, NULL, 'The sounding and ventilation of the ballast tank through the cargo hold was found in good condition with no indication of oil leakage.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2582, 121, 286, '1', NULL, NULL, 'The charts was not correctly updated.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2583, 121, 293, '1', NULL, NULL, 'The scupper plugs were not available onboard.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2584, 121, 294, '1', NULL, NULL, 'The oil absorbents was not available onboard.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2585, 121, 302, '1', NULL, NULL, 'The condition of  internal structural ballast tank no. 1 was found wasted at several places.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2586, 74, 172, '2', NULL, NULL, 'The safe manning certificate was available onboard at the time of the survey', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2587, 74, 173, '2', NULL, NULL, 'The crew list was available onboard with a total crew of 18 people, including the master. The number of crew that was onboard complied with the minimum safe manning requirement', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2588, 74, 174, '2', NULL, NULL, 'The officer certificate/endorsement were available in our pssesion at the time of the survey. All the officer certificate / endorsement are valid', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2589, 74, 175, '2', NULL, NULL, '<p>The class certificate for hull and machinery, including the load line, were maintained and up to date, the statutory certificates were also maintained and up to date.</p><p>Several ship certificate wil be due within the next 3 months as the following:</p><p>-Minimum safe manning document expired on 02 February 2024</p><p>-Rencana pola trayek (RPT) will expire on 03 February 2024</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2590, 74, 176, '2', NULL, NULL, 'The last special survey was carried out on 18 January 2023', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2591, 74, 177, '2', NULL, NULL, '<p>The last docking survey was carried out on 18 January 2023, concurenntly with the class special survey. The docking report is attached to this report</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2592, 74, 178, '1', NULL, NULL, 'No outstanding visa (recommendation) for machinery and hull class certificate exists', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2593, 74, 179, '1', NULL, NULL, 'rn                                            The planned maintenance system (PMS) was available onboard. However, the critical equiipment list was not included in it', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2594, 74, 180, '1', NULL, NULL, '<p>The PMS available oboard, Meanwhile. the spare parts inventory was listed separately from the PMS.</p><p>The daily fuel and lube oil consumption was not recorded in the engine logbook.</p><p>At the time of the survey, the vessel had not yet issued the ordering list addressed to the shore office.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2595, 74, 181, '1', NULL, NULL, 'Since the PMS was not listed with the exact date of the maintenance schedule for each item, the PMS list overdue maintenance record was not available onboard.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2596, 74, 182, '1', NULL, NULL, 'Since the PMS was not listed with the exact date of the maintenance schedule for each item, the reminders for pending item were not available onboard', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2597, 74, 183, '2', NULL, NULL, 'The vessel''s draught was measured and recorded in the deck logbook onevery voyage', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2598, 74, 184, '2', NULL, NULL, 'The last page of the logbook was left empty by the crew', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2599, 74, 185, '1', NULL, NULL, 'The stability booklet was not available onboard', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2600, 74, 186, '5', NULL, NULL, '<p>The guidelines on the stowage plan were unavailable for our inspectioan du to the type of the vessel being general cargo.</p><p>The cargo securing book approved by the class is not available onboard </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2601, 74, 187, '2', NULL, NULL, 'The UTM report was available in our possession after we disembarked from the vessel. The vessel''s steel structure;s diminution level is still below the class maximum allowable limit of 20%', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2602, 74, 188, '2', NULL, NULL, 'As far as we could ascertain, the port and starboard side from the fore to the aft shell plating and coating was found in fair condition, with light indentation sighted at places.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2603, 74, 189, '2', NULL, NULL, 'The deck plating was found in good condition and well painted', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2604, 74, 190, '1', NULL, NULL, 'The half of the draft marks at fore, midship, and aft not clearly marked. Meanwhile, the port and starboard load line marks are clear and visible', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2605, 74, 191, '2', NULL, NULL, 'The draft marks/load line were measured correctly', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2606, 74, 192, '1', NULL, NULL, '<p>The port bulwark stiffener connected with the forecastle deck slightly parted.</p><p>However, the other guardrails, walkaways, and ladders located in the main deck, poop deck, and accomodation deck were found in fair condition</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2607, 74, 193, '2', NULL, NULL, 'Generally, the windlass and winches structure were found in fair condition and good operation when tested', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2608, 74, 194, '2', NULL, NULL, 'The mooring ropes and wire were in good order', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2609, 74, 195, '2', NULL, NULL, 'The mooring work areas were non-slippery and orderly', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2610, 74, 196, '2', NULL, NULL, '<p>At the time of our survey, we could inspect the ballast tanks No 1P, and 25 since the other ballast tanks remained filled with water to maintainthe vessel stability.</p><p>The inspected ballast tank was in fair condition and free from significant wastage, pitting and scale</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2611, 74, 197, '1', NULL, NULL, 'The zinc anode on the inspected ballast tanks was found absent', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2612, 74, 198, '1', NULL, NULL, 'The pilot ladder was found broken on the wooden footing. Meanwhile, the vessel uses the portable steel ladeer for the temporal gangway', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2613, 74, 199, '2', NULL, NULL, '<p>The 1 (one) cargo crane was fitted onboard in the middle of hatches of cargo hold No. 1. The maintenance records were found to be kept, and lastly inpected by the class on 12 August 2020.The document is attached to this report. However the master verbally advised that the crew inspected the crane routinely.</p><p>The owner reprentative advised that the crane certificate exoired in 2013.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2614, 74, 200, '1', NULL, NULL, '<p>Generally, most mooring equipment (bollard,fairlead, rolled, capstan) is not clearly marked with safe working load (SWL) information.</p><p>Meanwhile, the steel structure was found to be in fair condition </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2615, 74, 201, '1', NULL, NULL, '<p>Several air vents or sounding pipes were not clearly marked with the compartment they served. Meanwhile, the steel structure was in fair condition and well color- coded.</p><p>The air vents were not provided with floaters</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2616, 74, 202, '2', NULL, NULL, '900 hours', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2617, 74, 203, '2', NULL, NULL, '<p>Replace the engine valve pipe and injector on 7 January 2024.</p><p>The maintenance record were not available for our inspection. The crew verbally advised that they perform maintenance by following the engine maker manuals.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2618, 74, 204, '2', NULL, NULL, 'The main engine photographs are attached to this report', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2619, 74, 205, '2', NULL, NULL, '<p>Engine 1 : 500 hours</p><p>Engine 2 : 500 hours </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2620, 74, 206, '2', NULL, NULL, '<p>Engine 1 : Replace the liner in october 2023</p><p>The maintenance records were not available for our inspection. The crew verbally advised that they perform maintenance by following the engine maker manuals.</p><p>Engine 2 : General overhaul in august 2023</p><p>The maintenance records were not available for our inspection. The crew verbally advised that they perform maintenance by following the engine maker manuals.<br></p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2621, 74, 207, '2', NULL, NULL, '<p>Engine 1 : The photographs of the auxiliary engine No. 1 are attached to this report.</p><p>Engine 2 : <span style=', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2622, 74, 208, '2', NULL, NULL, 'The lubrication oil pressure sensor''s calibration result was unavailable onboard for our inspection', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2623, 74, 209, '2', NULL, NULL, 'The vessel''s was only provided with the main and auxilairy engine manfacturer''s manual''s, while the manuals and bulletins for the other machinery equipment were absent', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2624, 74, 210, '2', NULL, NULL, 'The record of lubricant oil analysis was available in our possession after we disembarked from the vessel', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2625, 74, 211, '1', NULL, NULL, 'The telephony in the engine room was found out of order', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2626, 74, 212, '2', NULL, NULL, 'The engine room lighting was found adequate', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2627, 74, 213, '6', NULL, NULL, 'The emergency lighting in the engine room was not applicable', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2628, 74, 214, '2', NULL, NULL, 'Engine room was generally clean and dry', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2629, 74, 215, '2', NULL, NULL, 'The engine room ventilation was found adequate. The vessel was installed with one skylight and several additional blower fans', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2630, 74, 216, '2', NULL, NULL, '<p>The thermometer was available in the engine room</p><p>The temperature inside the engine room is approximately similar to that outside the engine room</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2631, 74, 217, '1', NULL, NULL, '<p>The engine room bilges were found wet with oily water</p><p>Meanwhile, the vessel complied with the ballst management</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2632, 74, 218, '2', NULL, NULL, 'The engine room bilge water level alarm/sensors were available and working properly. The alarm or notification was sigthted on the panel at the brigde', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2633, 74, 219, '2', NULL, NULL, 'The general condition of the engine room was found in fair condition', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2634, 74, 220, '2', NULL, NULL, 'The compressors were found in good condition, However, the purifiers were not fitted to the vessel', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2635, 74, 221, '2', NULL, NULL, 'The engine room pipe, valves, and coolers were in fair condition without any signs of leakage', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2636, 74, 222, '2', NULL, NULL, 'The engine room pipes were color-coded in accordance with the purpose', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2637, 74, 223, '2', NULL, NULL, 'The floor plates and the ladders were found in good condition and free from oil/oily', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2638, 74, 224, '2', NULL, NULL, 'The main switchboard indicator was in good condition and well maintained by the crew', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2639, 74, 225, '2', NULL, NULL, 'The engine indicator on the engine was found similar to the main swicthboard panel. The vessel was not fitted for the engine control room (ECR). Hence, the main switchboard panel was placed on the engine room''s top deck', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2640, 74, 226, '1', NULL, NULL, 'The insulation mats were absent on every engine switchboard panel, including the main switch panel and indicators', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2641, 74, 227, '2', NULL, NULL, 'The engine room stores were found to be well-stocked and properly arranged', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2642, 74, 228, '2', NULL, NULL, '<p>The workshop was clean, orderly, and completed with safe working equipment.</p><p><br></p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2643, 74, 229, '1', NULL, NULL, 'The watertight door in way of forepeak store was found chipped on the lower end', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2644, 74, 230, '2', NULL, NULL, 'Based on the visual inspection and engine logbook on the last voyage ,the main engine was found in good and satisfactory condition with no abnormality sighted', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2645, 74, 231, '2', NULL, NULL, 'The hot box and exhaust manifold were covered properly with lagging', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2646, 74, 232, '2', NULL, NULL, 'The exhaust temperature was found in satisfactory condition, with the evidence not exceeding 5 degrees difference compared with the outside temperature', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2647, 74, 233, '5', NULL, NULL, 'The occasion had not been ascertained yet because the main engine was not running', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2648, 74, 234, '2', NULL, NULL, '<p>The vessel was fitted with 1 (one) auxiliary engine of AE No. 1 as registered on the class certificate and 2 (two) additional generator sets.</p><p>The details of particular enginers are below:<br>-2 (two) enginers of AE No. 1 and genset No. 2 are located in the engine room</p><p>- 1 (one) engine of genset No. 3 is located on the boat deck</p><p>The crew verbally advised that the engine on the boat deck (genset No. 3) functioned as an emergency generator.</p><p>Based on the auxiliary engine daily record book, AE No. 1 and genset No. 2 and No. 3 are found in good and satisfactory condition with no abnormality sighted.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2649, 74, 235, '2', NULL, NULL, 'The hot box and exhaust manifold were covered properly with lagging', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2650, 74, 236, '1', NULL, NULL, 'The temperature measurment panel/indicator if auxilairy engine No. 1 was broken. Hence, the crew could not carry out the temperature measurement', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2651, 74, 237, '1', NULL, NULL, '<p>Genset No. 2 was not ascertianed yet due to the engine not running</p><p>Meanwhile, Genset No. 3 was freed from significant oil or water leakages and/or temporary drains during the emergency generator test.</p><p>The auxiliary engine No. 1 was found oil leakage on the engine valve pipe.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2652, 74, 238, '2', NULL, NULL, 'The inboard stern tube was in good condition and free from oil or waterl eakage', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2653, 74, 239, '2', NULL, NULL, 'The last propeller shaft was withdrawn, anad stern tube bearing clearance measurement was taken in Novemver-December 2022, when the last docking was performed.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2654, 74, 240, '2', NULL, NULL, '<p>The propeller condition has not yet been ascertained because the survey was carried out while the vessel was droped anchor at achorage area.</p><p>Based on the las docking report, the four propeller blades were cleaned and polished, and the NDT test was carried out during the previous docking.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2655, 74, 241, '2', NULL, NULL, 'The emergency steering is available for our test and was found in good order when tested', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2656, 74, 242, '2', NULL, NULL, 'The crew uses handy talku (HT) to communicate between the steering gear room and the bridge', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2657, 74, 243, '1', NULL, NULL, 'The emergency steering procedure was not available and posted in the steering room', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2658, 74, 244, '1', NULL, NULL, 'The record testing of steering gear synchronization between the steering and navigation room is not available onboard', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2659, 74, 245, '1', NULL, NULL, '<p>rn                                            The smoke detector alarm test record is not available onboard</p><p>Meanwhile, the smoke detector was only installed on the bridge deck and was found out of order</p><p>                                        </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2660, 74, 246, '2', NULL, NULL, 'The alleyways /stairs were free from obstruction/ defect objects', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2661, 74, 247, '1', NULL, NULL, 'The fire extinguisher and fire hose locker were found satisfactory condition and stowed adequately with sufficient numbers', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2662, 74, 248, '1', NULL, NULL, 'One piece of the main hydrant near the aft cargo hold was found missing on the valve. However, the other main hydrant was in good condition when tested', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2663, 74, 249, '1', NULL, NULL, 'The emergency power source (battery) and lighting were out of order', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2664, 74, 250, '2', NULL, NULL, 'The emertgency generator was found in order when testing. The vessel was fitted with 1 (one) emergency generatoe located on the boat deck', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2665, 74, 251, '2', NULL, NULL, 'The emergency fire pump test with separated hoses was available for our inspection and resulted in satisfactory condition', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2666, 74, 252, '1', NULL, NULL, 'The blackout procedure was not available and posted onboard', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2667, 74, 253, '2', NULL, NULL, 'The portable fire extinguisher is posted on each accomodation deck and is not overdue for the manual service', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2668, 74, 254, '2', NULL, NULL, 'The general alarm for crew accomodation was found in good condition during testing', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2669, 74, 255, '2', NULL, NULL, 'The emergency alarm for escape routes were posted in the crew accomodation', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2670, 74, 256, '1', NULL, NULL, 'Emergency light in crew accomodation was installed onboard, but the system was out of order when tested', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2671, 74, 257, '1', NULL, NULL, '<p>The gyro compass system in way of the master compass was out of order. Meanwhile, the other navigation and communication equipment was found in order when the flame test was carried out.</p><p>The list bridge navigation and communication equipment is attached to this report</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2672, 74, 258, '1', NULL, NULL, 'A copy the deviatin card for the compass is available on the bridge but has not been updated. The last calibration was carried out on 09 November 2020. The document is attached to this report', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2673, 74, 259, '1', NULL, NULL, 'The updated NTM (BPI-Berita Pelaut Indonesia) was not available onboard', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2674, 74, 260, '1', NULL, NULL, 'The chart was not correctly updated to cover the ship trading area', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2675, 74, 261, '2', NULL, NULL, 'The vessel condition was verified and recorded, including trim,draft, and intact stability. The crew recorded it in the deck logbook', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2676, 74, 262, '2', NULL, NULL, 'The crew adequately made and recorded the passage planning for every voyage from the initial port to the other port', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2677, 74, 263, '1', NULL, NULL, 'The master or C/O did not calculate stability at the time of departre anad arrival since the stability booklet was unavailable onboard', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2678, 74, 264, '1', NULL, NULL, 'The crew''s emergency steering procedure was not posted ion the bridge deck', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2679, 74, 265, '1', NULL, NULL, 'As far as we could ascertain, the cargo hold was generally found rusted, and the doubling plate was sighted at places', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2680, 74, 266, '1', NULL, NULL, 'The bilge in the cargo hold was found wet with water', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2681, 74, 267, '1', NULL, NULL, '<p>Booby hatch in way of the forepeak store, later connecting to the cargo hold found missing on the rubber sealing. The other booby hatch inside the forepeak store in way of the cargo hold was fitted with unpropped rubber sealed.</p><p>However, the hatch covers, coaming and other access rather than those mentioned above are astructurally found in good condition</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2682, 74, 268, '2', NULL, NULL, 'We could inspect the 3/4 part of the hatch cover since the rest was covered with tarpaulins. The insoected hatch cover and panels were correctly aligned.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2683, 74, 269, '2', NULL, NULL, '<p>The hatch cover was pontton type, sitting on the  coaming table (landing pads) without a compression bad and covered by tarpaulins as a securing device.</p><p>However, we could inpsect 1/4  part of the landing pads due to the other being covered with the hatch cover and tarpaulins. The inspected landing pads were structrully found in order</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2684, 74, 270, '2', NULL, NULL, 'The internal condition cargo hold of the cargo space was found clean and dry', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2685, 74, 271, '1', NULL, NULL, 'As far we could ascertain, the cargo hold steel structure was generally found rusted, and the doubling plate was sighted at places', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2686, 74, 272, '2', NULL, NULL, 'According to our visul inspection, the thickness of the hatch cover is still sufficient', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2687, 74, 273, '6', NULL, NULL, 'Not Applicable', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2688, 74, 274, '2', NULL, NULL, 'The booby hatches leading to the cargo hold are used for temporal ventilation, and it was found in good condition for sufficient air acsess', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2689, 74, 275, '6', NULL, NULL, 'Not Applicable', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2690, 74, 276, '1', NULL, NULL, 'Several toe bracket inside the cargo hold were found parted and buckler at places', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2691, 74, 277, '6', NULL, NULL, 'Not Applicable', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2692, 74, 278, '5', NULL, NULL, 'The crew explained that the cargo holds bilge suction pipe was disconnected from the suction pump located in the engine room. Hence, the suction test was not carried out during our survey.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2693, 74, 279, '1', NULL, NULL, 'The sounding and ventilation pipe of the ballast tanks through the cargo hold was found rusted at places, but there is no incication of leak.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2694, 82, 172, '2', NULL, NULL, 'The safe manning certificate was available onboard the vessel', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2695, 82, 173, '2', NULL, NULL, 'The crew list is available and in our possession with a total crew of 16 people, including the master', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2696, 82, 174, '2', NULL, NULL, 'The officer certificates/endorsements were valid and available in our possession.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2697, 82, 175, '2', NULL, NULL, 'The class certificates for hull and machinery, including the load line, were in provisional condition and were maintained and up to date.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
