INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2778, 82, 256, '6', NULL, NULL, 'The vessel was not equipped with emergency lighting, the crew advised that all  lighting would automatically turn on when the emergency generator operate.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2779, 82, 257, '2', NULL, NULL, 'All the navigational equipment was found in order when tested and completed as per equipment list.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2780, 82, 258, '2', NULL, NULL, 'A copy of the deviation card for the compass is available on the bridge. The document is attached to this report.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2781, 82, 259, '2', NULL, NULL, 'The NTM (BPI- Berita Pelaut Indonesia) was available onboard and updated. The crew stored it on the vessel''s computer at the bridge.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2782, 82, 260, '1', NULL, NULL, 'The charts was recorded and covered he ship''s trading area. However, the chart was not updated, and the crew only marked the chart as per update from BPI.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2783, 82, 261, '2', NULL, NULL, 'The vessel condition was verified and recorded, including trim, list, draft, and intact stability.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2784, 82, 262, '2', NULL, NULL, 'The crew adequately made and recorded the passage planning in the last voyage.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2785, 82, 263, '2', NULL, NULL, 'The crew only made master sailing declaration at the time of departure an arrival. The doucment is later attached on this report.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2786, 82, 264, '1', NULL, NULL, 'The emergency steering procedure was not posted at the bridge deck.However, the crew was similar with the emergency steering operation.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2787, 82, 265, '2', NULL, NULL, 'The cargo hold was found in fair condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2788, 82, 266, '1', NULL, NULL, 'The port bilges was filled with water.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2789, 82, 267, '2', NULL, NULL, 'Structurally, the cargo tahct covers, coamings, and access hatches were found in fair condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2790, 82, 268, '2', NULL, NULL, 'The hatch cover panel was found correctly aligned and secured.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2791, 82, 269, '6', NULL, NULL, 'The vessel was not equipped with compresssion bars, landing pads, and securing devices.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2792, 82, 270, '1', NULL, NULL, 'The internal condition of the cargo hold space was found wet to the hatch cover was opened and rain prevailed.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2793, 82, 271, '1', NULL, NULL, 'The tanktop of cargo hold was found indented at several places and there was a doubling at tanktop. However, the other steel structures and hatch cover pontoons were found satisfactory and well coated.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2794, 82, 272, '2', NULL, NULL, 'According to our visual inspection, the thickness of the hatch cover is still sufficient.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2795, 82, 273, '6', NULL, NULL, 'The seal and compression bars were not applicable on this vessel. The vessel was using hatch cover pontoons and later covered by tarpaulin.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2796, 82, 274, '2', NULL, NULL, 'The cargo space ventilation was found in good condition for sufficient air access.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2797, 82, 275, '6', NULL, NULL, 'Not Applicable.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
