INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2800, 82, 278, '1', NULL, NULL, 'The bilge wells suction test was carried out at the time of our survey and the starboard bilge suction test found satisfactory. However, the port bilge suction test could not be carried out due to the crew balnked off the suction pipe.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2801, 82, 279, '1', NULL, NULL, 'The sounding and pipe of the ballast tanks through the caro hold was found in good condition and there were no indication of leak or corrosion sighted.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
