INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2955, 202, 295, '2', NULL, NULL, '<div>The sighted port and starboard side hull was visually found in fair condition, and the painting works with light indentation at places.</div><div><br></div><div>Meanwhile, the port and starboard side draft mark and load lines were clearly marked and visible.</div>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2956, 202, 296, '1', NULL, NULL, 'Most bollard was not marked with safe working load (swl) information.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2957, 202, 298, '2', NULL, NULL, 'The internal condition, including the steel structure of the cargo hold, was found in fair condition with the slightly buckled at places. rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2958, 202, 300, '2', NULL, NULL, 'The hatch cover was pontoon type, sitting on the coaming table and covered by tarpaulins as a securing device.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2959, 202, 301, '6', NULL, NULL, 'Not Applicable.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2960, 202, 302, '2', NULL, NULL, 'The inspected internal condition of ballast tank was found in fair condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2961, 202, 303, '5', NULL, NULL, 'rn                                            rn                                            Not Inspected. At time of survey the ballast pump out of order', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2962, 202, 304, '2', NULL, NULL, 'In good running condition without any sign of significant leaking sighted. The main engine also was in trustworthy.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2963, 202, 305, '2', NULL, NULL, 'rn                                            The emergency generator was found in order when tested. The engine located in the steering room.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2964, 202, 306, '2', NULL, NULL, '<div>The vessel was fitted with 3 (three) auxiliary engines of AE No. 1 as registered on the class certificate and 2 (two) additional generator sets.</div><div><br></div><div>The details of particular engines are below:</div><div>- 1 (one) engine of AE No. 1 is located in the engine room,</div><div><br></div><div>- 1 (one) engine of Additional Generator Engine is located on the poop deck.</div><div>- 1 (one) engine of Emergency Generator is located in the steering room.</div><div><br></div><div>All Auxiliary Engines coundition were found in well maintened without any sign of excessive oil drain sighted.</div>rn                                            rn                                            <p><span style=', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2965, 202, 307, '2', NULL, NULL, 'The crew use telephone.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2966, 202, 308, '2', NULL, NULL, 'The emergency steering test was in order when tested.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (2967, 202, 294, '1', NULL, NULL, 'The oil absorbents was not available onboard.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
