INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3007, 130, 120, '2', NULL, NULL, 'rn                                            The echo sounder was found in order.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3008, 130, 121, '2', NULL, NULL, 'The emergency steering instructions were available and posted on the bride deck and steering room.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3009, 130, 122, '1', NULL, NULL, 'rn                                            rn                                            The SOPEP locker complete with it''s contents wasn''t available on board.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3010, 130, 123, '1', NULL, NULL, 'rn                                            rn                                            The bunkering connections were found without save-alls.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3011, 130, 124, '1', NULL, NULL, 'rn                                            rn                                            The fuel air vent, ventilation pipe, and sounding pipe were not marked with the compartment they serve.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3012, 130, 125, '2', NULL, NULL, 'Save-alls provided on the surrounding the machinery equipment and which equipment.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3013, 130, 126, '1', NULL, NULL, 'The scupper plugs were not available onboard.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3014, 130, 127, '1', NULL, NULL, 'The oil absorbents were not available onboard.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3015, 130, 128, '2', NULL, NULL, 'rn                                            <p>rn                                            The sighted port and starboard side hull were visually found in fair condition, and the painting works with light indentation and scratches at places.</p><p>The draft mark and load lines were clearly marked and visible.</p><p><br></p><p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3016, 130, 129, '1', NULL, NULL, 'rn                                            rn                                            <p>rn                                            The conditions of all decks in fair condition. Most bollards were not marked with safe working load (SWL) information.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3017, 130, 130, '1', NULL, NULL, 'rn                                            rn                                            The watertight door was found to be severely corroded, and the rubber seal was hardened.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3018, 130, 131, '2', NULL, NULL, 'The interior of holds was found in fair condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3019, 130, 132, '2', NULL, NULL, 'The cargo hold bilges were found clean, and the suction test was carried out using a portable pump with good operation testing results.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3020, 130, 133, '1', NULL, NULL, 'rn                                            <p>The hatch cover was the folding type and covered by tarpaulins as a securing device.</p><p>However, the hatch cover was found to be wasted in several spots. The rubber seal was found missing and hardened.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3021, 130, 134, '6', NULL, NULL, NULL, NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3022, 130, 135, '1', NULL, NULL, 'rn                                            The inspected internal condition of the ballast tank was found to be in fair condition and corrosion was sighted at places.<br><br>Meanwhile, the associated zinc anode was found fully depleted in the internal of ballast tanks No. 2S and 2P.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3023, 130, 136, '2', NULL, NULL, 'The ballast tank pressure test result was satisfactory.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3024, 130, 137, '2', NULL, NULL, 'In good running condition without any sign of significant leaking sighted, the main engine was also trustworthy.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3025, 130, 138, '2', NULL, NULL, 'rn                                            <p>Located in the boat deck and was found in order when tested.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3026, 130, 139, '2', NULL, NULL, 'rn                                            rn                                            rn                                            rn                                            rn                                            <p>The vessel was fitted with 2 (two) auxiliary engines and 2 (two) generator sets. The auxiliary engines No. 1 and 2 are registered on the class certificate.</p><p>The details of particular engines are below:</p><p>- 2 (two) engines of AE No.1 and AE 2 are located in the engine room,</p><p>- 1 (one) engine generator engine is located on the boat deck. </p><p>- 1 (one) engine of the emergency generator is located on the boat deck.</p><p>The auxiliary engine condition was found in well maintained without any sign of excessive oil drain sighted.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3027, 130, 140, '2', NULL, NULL, 'The crew use telephone.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
