INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3480, 201, 135, '2', NULL, NULL, '<p>rn                                            The inspected internal condition of the ballast tank was found to be in fair condition and corrosion was sighted at places.</p><p><br>Meanwhile, the associated zinc anode fitted with sufficient numbers of sacrificial anodes in the internal of ballast tanks No. 2 Port and 2 Starboard.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
