INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3592, 129, 128, '2', NULL, NULL, '<p>The sighted starboard and port side hull were found in fair condition, and the painting works with light indentation and scratches at places.</p><p>The draft mark and load lines were clearly marked and visible.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3593, 129, 129, '2', NULL, NULL, 'The condition of all decks in fair condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3594, 129, 130, '2', NULL, NULL, 'The watertight door was found in order.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3595, 129, 131, '2', NULL, NULL, 'The interior of holds was found to be in fair condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3596, 129, 132, '2', NULL, NULL, 'Cargo hold bilges were found clean, and the suction test was carried out with good operation testing results.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3597, 129, 133, '1', NULL, NULL, 'rn                                            <p>The hatch cover was the folding type and covered by tarpaulins as a securing device.</p><p>The rubber seals on the hatch cover were found to be partially detached.</p><p><br></p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3598, 129, 134, '6', NULL, NULL, NULL, NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3599, 129, 135, '1', NULL, NULL, 'The inspected internal condition of ballast tanks No. 3S and 3P are generally corroded, and the associated zinc anodes were found to be fully depleted.<br>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3600, 129, 136, '2', NULL, NULL, 'The ballast tank pressure test result was satisfactory.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3601, 129, 137, '2', NULL, NULL, 'In good running condition without any sign of significant leaking sighted, the main engine was also trustworthy.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3602, 129, 138, '2', NULL, NULL, 'Located on the boat deck and was found in order when tested.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3603, 129, 139, '2', NULL, NULL, 'rn                                            rn                                            rn                                            rn                                            rn                                            The vessel was fitted with 3 (three) auxiliary engines and 2 (two) generator sets. The auxiliary engines No.1, 2, and 3 are registered on the class certificate.<br><br>The details of particular engines are below:<br><br>- 3 (three) engines of AE No.1, 2, and 3 are located in the engine room,<br><br>- 1 (one) engine generator set is located on the engine room,<br><br>- 1 (one) engine of the emergency generator is located on the boat deck.<br><br>The auxiliary engine condition was found to be well maintained without any sign of excessive oil drain sighted.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3604, 129, 140, '2', NULL, NULL, 'The crew use telephone.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3605, 129, 141, '2', NULL, NULL, 'rn                                            The emergency steering test was in order when tested.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3606, 375, 36, '2', NULL, NULL, '5000 Hours', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3607, 375, 1, '2', NULL, NULL, 'The Safe Manning Certificate was available in our possession at the time of the surveyrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3610, 375, 37, '2', NULL, NULL, 'rn                                            The Main engine was carried out General Overhaul last docking in February 2024. However, the maintenance record was follow the engine maker manual was not availlable onboard.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3611, 375, 38, '2', NULL, NULL, 'rn                                            rn                                            The Main Engine condition was found in well maintained without any sign of excessive oil drain sighted.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3612, 375, 39, '2', NULL, NULL, 'rn                                            1200 Hours', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3613, 375, 41, '2', NULL, NULL, 'rn                                            rn                                            rn                                            <p>The vessel was fitted with 2 (two) auxiliary engines of AE No. 1 and No. 2 as registered on the class certificate and 2 (two) Emergency generator sets.</p><p>The details of particular engines are below:</p><p>- 2 (two) engine of AE no. 1 and 2 is located in engine room.</p><p>- 1 (one) engine of Emergency Generator is located in poop deck.</p><p>- 2 (two) generator set is located in poop deck.</p><p>All auxiliary engines condition were found in well maintened without any sign of excessive oil drain sighted.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3614, 375, 2, '2', NULL, NULL, 'The crew list is available in our possession with a total crew of 14 people, including the Master. The number of crew onboard complied with the minimum requirement as mentioned in the safe manning certificate.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3615, 375, 3, '2', NULL, NULL, 'The Officer certificates/endorsements were available in our possession at the time of the survey. All the Officer Certificates/Endorsements are valid.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3616, 375, 4, '2', NULL, NULL, 'The class certificates for hull and machinery, including the load line, were maintained and up to date. The statutory certificates were also maintained and up to date. All the certificate was valid without due in the next 3 months.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3617, 375, 5, '2', NULL, NULL, 'rn                                            rn                                            <p>The last special survey was carried out on 2021.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3618, 375, 6, '2', NULL, NULL, 'The last docking survey was carried out on 13 Februari 2024, concurrently with the class intermediate survey. The docking report is attached to this report.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3619, 375, 7, '2', NULL, NULL, 'No outstanding visa (recommendation) for machinery and hull class certificate exists.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3620, 375, 8, '1', NULL, NULL, 'Planned maintenance system include critical equipment was not available onboard.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3621, 375, 9, '1', NULL, NULL, 'rn                                            The planned maintenance system include spareparts inventory list the overdue maintenance record.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
