INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3623, 375, 11, '1', NULL, NULL, 'Reminders for pending items were not available onboard.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3624, 375, 12, '2', NULL, NULL, 'The vessel''s draught was measured and recorded in the deck logbook.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3625, 375, 13, '2', NULL, NULL, 'rn                                            The last page of the logbook was left empty by the crew.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3626, 375, 14, '1', NULL, NULL, 'The stability booklet was not available onboard.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3627, 375, 15, '1', NULL, NULL, 'The company does not issue guidelines on the stowage plans and the cargo securing book approved by the class is not availablern', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3628, 375, 16, '2', NULL, NULL, 'The UTM report was available. The vessel''s steel structures'' diminution level is still below the class maximum allowable limit of 20%.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3629, 375, 17, '2', NULL, NULL, 'rn                                            The sighted starboard and port side shell plating from aft to fore-ends, from the sheer down to the waterline, was visually found to be in fair condition, with fair painting work and light indentations observed at places.<br>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3630, 375, 23, '2', NULL, NULL, 'rn                                            The deck plating on the forecastle, main, and poop deck was found to be in fair condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3631, 375, 24, '2', NULL, NULL, 'The portside and starboard side draft marks/ load lines were clearly marked and visible.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3632, 375, 25, '2', NULL, NULL, 'The draft marks/ load lines were measured correctly.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3633, 375, 26, '1', NULL, NULL, 'The guardrails on the port side of the vessel were removed due to modifications to the lifeboat pathway and have not been restored to the original conditions.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3634, 375, 27, '2', NULL, NULL, 'rn                                            The windlasses, deck winches , and anchor equipment are in apparent good order, but the windlasses are already corroded', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3635, 375, 28, '2', NULL, NULL, 'The mooring ropes and wires are in apparent good order.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3636, 375, 29, '3', NULL, NULL, 'The mooring works areas are non-slippery.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3637, 375, 30, '1', NULL, NULL, 'At the time of our survey, we could inspect 2 (two) ballast tanks, which consist of ballast tanks No. 3P and No. 3S. <br><br>The ballast tanks, complete with the internals structure, were corroded and pitting.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3638, 375, 31, '1', NULL, NULL, 'The ballast tank No.3P and No.3S were found without any zinc anode installed.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3639, 375, 32, '6', NULL, NULL, 'rn                                            The vessel was not applicable with the gangway.<br>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3640, 375, 33, '1', NULL, NULL, 'The ship''s lifting appliance and loose gear maintenance records, complete with cargo gear certificate, were not available onboard.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3641, 375, 34, '1', NULL, NULL, 'The condition of deck equipment was not clearly marked with safe working load (SWL) information. <br><br>Meanwhile, structurally, the mooring equipment was found in fair condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (3642, 375, 35, '1', NULL, NULL, 'The vents and air/sounding pipes on the deck were not clearly marked with the compartment they served.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
