INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (4395, 426, 133, '2', NULL, NULL, 'rn                                                                                       <br><p>The hatch cover was the folding type and was covered by tarpaulins as a securing device.</p><p>The rubber seals on the hatch cover were found to be partially detached.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
