INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (4397, 426, 135, '2', NULL, NULL, 'rn                                                                                        <br>At the time of our survey, we could inspect the 4 (four) ballast tanks which consist of ballast tanks No. 3P, 3S No. 4S, and No. 4P. The ballast tanks were found in fair condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (4398, 426, 136, '5', NULL, NULL, 'rn                                                                                       <br>The ballast tank pressure test could not be conducted due to the vessel was at sea. The crew verbally advised that the vessel filled the ballast tanks while on the river and never filled the ballast tanks while at sea.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (4399, 426, 137, '2', NULL, NULL, 'rn                                                                                       <br>In good running condition without any sign of significant leaking sighted, the main engine was also trustworthy.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (4400, 426, 138, '2', NULL, NULL, 'rn                                            rn                                            rn                                                                                       <br>Located in the emergency steering gear room', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (4401, 426, 139, '2', NULL, NULL, 'rn                                                                                         <br><p>The vessel was fitted with 2 (two) auxiliary engines and 1 (one) emergency generator. The auxiliary engines No.1 and 2 are registered on the class certificate.</p><p>The details of particular engines below:</p><p>- 2 (two) engines of AE No. 1 and 2 are located in the engine room,</p><p>- 1 (one) engine of the emergency generator is located on the steering gear room.</p><p>The auxiliary engine''s condition was found to be well maintained with no sign of excessive oil drain sighted and was found to work in order.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
