INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6115, 623, 115, '2', NULL, NULL, '<p>rn                                            rn                                            rn                                            rn                                            UTM Report was found not available on board but further has been provided (Rectified). </p><p>Having reviewed UTM Report no. 341/SPK/TEK/UT/VI/2025 measuring date 01 June 2025 at PT. Indonesia Marina Shipyard issued by PT. Sanjaya Putra Kencana, we noted that the maximum diminutions is still below 20%.</p><p>                                                                                                                         </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
