INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6285, 617, 987, '1', NULL, NULL, 'rn                                            rn                                            <ol><li>Hydraulic of mooring windlass at stern was found leakage. But, after complete survey the ship''s crew has repaired. (Rectified)</li><li>Mooring line of fore and stern windlass were found in poor condition. But, after complete survey the ship''s crew has repaired. (Rectified)</li><li>Some of fairlead construction were found wastage condition. </li><li>All bollards were found not mark with SWL. But, after complete survey the ship''s crew has repaired. (Rectified)</li></ol>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
