INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6328, 621, 129, '1', NULL, NULL, 'rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            <p>- Main deck was found rusty</p><p>- Bulwark was found heavy corroded</p><p>- Railings were found partly missing and broken/ corroded</p><p>- Stanchion, Top plate and Longitudinal Stiffener of Hatch coamings were found heavy corroded</p><p>- Hydraulic operating handles of Hatch cover were found leakages</p><p>- Vertical ladders on external Hatch coaming were found heavy corroded</p><p>- Hydrant pipe on Main deck was found leakages</p><p>- All inclined ladders on outside accommodation were found corroded</p><p>- Many doublers were found at forward deck</p><p>- Chain stopper of Anchor and Mooring Windlass (S) was found missing</p><p>- Hydraulic pipe of Anchor and Mooring Windlass was found tightened with rubber ban</p><p>- Drums of Aft Mooring Winches were found partly corroded</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6329, 621, 130, '1', NULL, NULL, 'Watertight doors access to accommodation and cargo hold were found corroded & without Open/ Close marking', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6330, 621, 131, '1', NULL, NULL, 'Interior of Cargo hold was found rusty and tank top not clean (found cargo residue)', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6331, 621, 132, '2', NULL, NULL, '<p>- Cargo hold bilge was found in fair condition</p><p>- Suction test has been carried out and found in satisfactory condition</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6332, 621, 22, '2', NULL, NULL, '<p>rn                                            rn                                            Class Certificate was found not available on board, but further the valid Class Certificate was provided (Rectified)</p><p>                                          </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6333, 621, 115, '2', NULL, NULL, 'rn                                            <p>rn                                            UTM Report was found not available on board, but further has provided (Rectified)</p><p>Having reviewed UTM Report no. 115/KJM/UTM/III/24 Measuring date 24 February 2024 at PT. Dewa Ruci Agung issued by PT. Kava Jaya Mandiri, we noted that the maximum diminutions is still below 20%</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
