INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6426, 602, 128, '1', NULL, NULL, 'rn                                            <ol><li>HULL WAS GENERALLY FOUND IN A RUSTY CONDITION</li><li>DRAUGHT AND LOADLINES WERE FOUND FADED<br><br></li></ol>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6427, 602, 129, '1', NULL, NULL, 'rn                                            <ol><li>MAIN DECK WAS FOUND RUSTY</li><li>BULWARK WAS FOUND RUSTY AND PARTLY CORRODED</li><li>RAILING WAS FOUND PARTLY MISSING</li><li>BOLLARD, ROLLER, & FAIRLEADS WERE FOUND WITHOUT SWL MARKING & IN A RUSTY CONDITION</li><li>BOLLARD (STBD-FWD) WAS FOUND CORRODED</li><li>FORWARD & AFT WINCHES WERE FOUND RUSTY & PARTLY CORRODED</li><li>COAMING STAY OF CH 1 & 2 WERE FOUND RUSTY AND PARTLY CORRODED</li></ol>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6428, 602, 130, '1', NULL, NULL, '<ol><li>WATERTIGHT DOORS WERE FOUND WITHOUT OPEN/CLOSE DIRECTION MARKING</li><li>FORWARD WATERTIGHT DOOR ACCESS TO FORWARD STORE AND CH NO. 1 WAS FOUND CORRODED</li></ol>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
