INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6433, 602, 135, '1', NULL, NULL, '<ol><li>THE INTERNAL STRUCTURE OF WBT WAS FOUND RUSTY AND POSSIBLY SERIOUS CORROSION TO WBT 3 & 4 STARBOARD SIDE</li><li>WBT NO. 3 & 4 ( STARBOARD SIDE) WERE FOUND CONTAMINATED WITH OIL</li></ol>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6434, 602, 136, '1', NULL, NULL, '<p>BALLAST TANKS PRESSURE TEST WAS NOT CARRIED OUT DUE TO:</p><ol><li>THE CREWS OPENED ALL OF THE BALLAST TANK MANHOLES</li><li>BASED ON VERBAL INFORMATION FROM THE CREW, THAT ANY BOTTOM GIRDER WAS FOUND BROKEN BEFORE WE ATTEND THE VESSEL</li></ol>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6435, 602, 137, '2', NULL, NULL, '<p>rn                                            CONDITION OF THE ENGINE ROOM WAS FOUND IN FAIR CONDITION. HOWEVER;<br>- 1 OF BALLAST PUMP WAS FOUND IN TEMPORARY REPAIR</p><p>- EMERGENCY LIGHTING & BILGES ALARM WERE FOUND MALFUNCTION</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
