INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6514, 588, 127, '1', NULL, NULL, 'Oil absorbents were found not available', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6515, 588, 128, '5', NULL, NULL, 'rn                                            rn                                            The visible hull plating, coating and marking was found in fair condition, but several areas of hull such as port side hull and stern not inspected due no access', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6516, 588, 129, '1', NULL, NULL, 'rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            <p>rn                                            - Main deck was found rusty</p><p>- Doubler was found below watertight door access to accommodation (S)</p><p>- Railings on main deck (P & S) were found partly rusty</p><p>- Forward store (Below forward deck) was found heavy rusty</p><p>- CO2 room was found messy/ obstructed with foreign materials</p><p>- Windlass were found rusty and gear of windlass corroded</p><p>- Anchor chains were found rusty</p><p>- Mooring line of Aft Winches were found abrasive</p><p>- Bollards, Rollers, and Fairleads were found without SWL marking</p><p>- Endcaps of rollers and fairleads were found partly missing</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6517, 588, 130, '1', NULL, NULL, 'rn                                            <p>- Watertight doors of Aft accommodation access, engine room and bosun store were found corroded at below side</p><p>- Watertight doors were found without Open/ Close marking and watertight doors of engine room without Kept Close at Sea marking</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6518, 588, 131, '1', NULL, NULL, 'rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            <p>- Tank top was found rusty</p><p>- Tween deck was found rusty and partly corroded</p><p>- Doublers were found on Tween deck</p><p>- Port side Web frame no. 79 was found dented</p><p>- Cargo holds at aft area was found flooded</p><p>- Hatch coaming cantilever face plate were found partly deformed</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6519, 588, 132, '5', NULL, NULL, 'rn                                            rn                                            Cargo hold bilge has not been inspected due to flooded cargo hold at aft area and suction test has not been carried out due to operational reason', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6520, 588, 134, '5', NULL, NULL, 'Hose test has not been carried out due to operational reasons', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6521, 588, 133, '1', NULL, NULL, 'rn                                            rn                                            rn                                            rn                                            rn                                            <p>- Hatch covers were found corroded</p><p>- Rack and pinion drive was found leaking</p><p>- Rubber sealing was found partly hardened</p><p>                                        </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6522, 588, 135, '5', NULL, NULL, 'The internal structure of WBT has not been inspected due to operational reasons', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6523, 588, 136, '5', NULL, NULL, 'WBT pressure test has not been carried out due to operational reasons', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6524, 588, 141, '1', NULL, NULL, 'rn                                            rn                                            Steering was found still being repaired (rudder stock is being dismantled)', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6525, 588, 140, '2', NULL, NULL, 'Yes', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
