INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6528, 588, 137, '2', NULL, NULL, 'Yes', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6529, 588, 116, '1', NULL, NULL, 'rn                                            Radar was found malfunction due to electrical power supply burned out', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6530, 643, 22, '2', NULL, NULL, 'rn                                            Class certificates were not available on board during initial inspection. However, upon further verification, class certificates were provided and found to be valid (Rectified). No class recommendation or exemption certificates were noted.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6531, 643, 114, '2', NULL, NULL, 'All officers appeared competent and familiar with this type and size of vessel. Competency and proficiency certificates were available and valid as per STCW standards. Watchkeeping arrangements were found to be satisfactory.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6532, 643, 115, '2', NULL, NULL, 'Ultrasonic thickness measurement (UTM) report was not sighted on board during inspection but was subsequently provided. Last UTM report dated 24 May 2023 conducted during drydocking at Dock Mariana Bahagia Palembang, the report is class approved with maximum diminution noted still below 20%. (Rectified)', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6533, 643, 116, '2', NULL, NULL, 'rn                                            Radar system was checked and tested, found to be functioning properly. Performance test demonstrated satisfactory target detection and tracking capabilityrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6534, 643, 117, '2', NULL, NULL, 'Magnetic compass fitted on board, found in good condition and operational. Deviation card was posted on bridge', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6535, 643, 120, '2', NULL, NULL, 'Echo sounder was tested and found to be operational. Depth readings were accurate and display was functioning correctlyrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6536, 643, 123, '2', NULL, NULL, 'Bunkering connections were inspected and found to be in satisfactory condition. All flanges, valves, and blank flanges were available and properly maintained.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6537, 643, 134, '6', NULL, NULL, 'Vessel is equipped with lifting pontoon type hatch cover, utilizing 3-layer tarpaulin on hatch cover as weathertight/water leakage prevention method. Due to this design configuration, ultrasonic/hose test is not applicable. Tarpaulin condition and securing arrangements were inspected and found in serviceable condition.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6538, 643, 136, '2', NULL, NULL, 'Ballast tank pressure test was conducted as per requirements. All DBWT held pressure satisfactorily with no leakage as visible through cargo hold.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6539, 643, 140, '2', NULL, NULL, 'Direct telephone between steering gear and bridge was provided tested in working condition', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6540, 643, 141, '2', NULL, NULL, 'Emergency steering system was tested and found to be operational. Changeover from main to emergency steering was accomplished satisfactorilyrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6541, 643, 141, '2', NULL, NULL, 'Emergency steering system was tested and found to be operational. Changeover from main to emergency steering was accomplished satisfactorilyrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6542, 643, 141, '2', NULL, NULL, 'Emergency steering system was tested and found to be operational. Changeover from main to emergency steering was accomplished satisfactorilyrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6543, 643, 116, '2', NULL, NULL, 'rn                                            Radar system was checked and tested, found to be functioning properly. Performance test demonstrated satisfactory target detection and tracking capabilityrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6544, 643, 118, '1', NULL, NULL, 'Notice to Mariners (NTM) BPI weekly was not available on board at the time of inspectionrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6545, 643, 119, '1', NULL, NULL, 'Navigational charts were found to be sufficient for vessel''s trading area, however charts were not updated/corrected due to unavailability of NTM BPI on board.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6546, 643, 121, '1', NULL, NULL, 'Emergency steering changeover procedure was not sighted on bridge during inspectionrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6547, 643, 122, '1', NULL, NULL, 'SOPEP locker and equipment were not available on deck at the time of inspectionrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6548, 643, 124, '1', NULL, NULL, 'rn                                            rn                                            Fuel oil vents on deck were inspected and operational, however they were not labeled as per served', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6549, 643, 125, '1', NULL, NULL, 'rn                                            Bunker station and air vents were not fitted with save-allsrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6550, 643, 126, '1', NULL, NULL, 'Scupper plugs were not sighted on boardrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6551, 643, 127, '1', NULL, NULL, 'Oil absorbents were not sighted on boardrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6552, 643, 128, '1', NULL, NULL, 'Major rust was sighted at several areas of external hull and rust stain were noted at ship name marking. Heavy damage on half-round steel fender on portside, approximately 2 meters length, was observedrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6553, 643, 129, '1', NULL, NULL, 'rn                                            Heavy corrosion was sighted on forward deck, forecastle store floor plate, and forward/aft winch foundation plate. Heavy corrosion and damage were observed at T-bollard forward, forward bulwark, and several sections of railing around main deckrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6554, 643, 130, '1', NULL, NULL, 'Heavy corrosion and damage were sighted at several watertight doors including aft & starboard side poop deck, and forecastle store.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6555, 643, 131, '1', NULL, NULL, 'rn                                            Overall internal cargo holds were intact but found rusted in general and hold tank tops were found with no coating. Coating condition was poor with extensive scaling and corrosion.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6556, 643, 132, '1', NULL, NULL, 'Bilge suction in cargo hold could not be tested as it was not working. Vessel currently uses portable pump to discharge bilge from cargo holdrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6557, 643, 133, '1', NULL, NULL, 'Heavy corrosion was sighted on hatch pontoon and top areas of hatch coamingrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6558, 643, 135, '1', NULL, NULL, 'rn                                            rn                                            Vessel was in ballast condition during inspection, all the BWT were full. We inspected the FPT and found with heavy corrosion, some cracks and deformation were sighted.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6559, 643, 137, '2', NULL, NULL, '<p>Main engine general condition appeared satisfactory and well-maintained, no significant oil leakage were sighted during inspection</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6560, 643, 138, '1', NULL, NULL, 'rn                                            Emergency generator located on boat deck starboard side, also functioning as additional generator, was observed without save-alls installed underneath.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6561, 643, 139, '1', NULL, NULL, 'rn                                            Generator No. 2 was under repair during inspection time, therefore not tested. Generator No. 1 and 3 was tested and found operational with satisfactory performancern', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
