INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6868, 680, 129, '1', NULL, NULL, 'rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            <p>- Main deck was found rusty at port and starboard side of cargo hold</p><p>- Hatch coaming was found heavy corroded</p><p>- Derrick deck foundations were found heavy corroded</p><p>- Bulwark was found heavy corroded</p><p>- Most of the railing were found heavy corroded, dented, and partly missing</p><p>- Anchor windlass and Aft Mooring winch foundations were found corroded</p><p>- Mooring lines of port side Anchor & mooring windlass, and Starboard side Aft mooring winches were found abrasive</p><p>- Hydrant pipe at starboard side main deck was found corroded and tightened with rubber ban</p><p>- Hydraulic systems (Pipelines and Hydraulic engine) of derricks (Aft and Fore) were found leakages</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
