INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6894, 695, 128, '4', NULL, NULL, 'The port and starboard external side shell plating above the water line found well coated.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6895, 695, 129, '4', NULL, NULL, 'Main Deck, forecastle and poop deckfound in satisfactory condition and well coated. No significant damage was observed on the pipe lines, bulkwarks, fairleads and other fittings on deck.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6896, 695, 130, '1', NULL, NULL, '<p>- Only one (1) piece from six (6) pieces of Watertight door’s clip at port and starboard side were function well, meanwhile for remained of five (5) pieces were not function or incomplete or missing. </p><p>- Only one (1) piece from six (6) pieces of Engine Room Watertight door’s clip at aft side were function well, meanwhile for remained of five (5) pieces were not function due to jammed. </p><p>- Engine Room Watertight door’s not marked with open / close direction.rn                                                                                          </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6897, 695, 131, '1', NULL, NULL, '<p>- Inspection to cargo hold was carried out and found the steel structure of cargo hold was in worn down paint coating, sligthly rust at severalas places. </p><p>- Found holes on top tank deck plate at fore side or on water ballast tank No. 1 centre and at wall starboard side plate.rn                                                                                          </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6898, 695, 132, '1', NULL, NULL, '<p>- The hold’s bilge was found to contain residual water and remnants of previous cargo. </p><p>- We were not carried out the suction test due to both of the bilge valve in Engine Room were jammed. </p><p>- For pump out the water in cargo hold bilge, the ship’s crew used portable pump with capacity of 25 m3/ hour.rn                                                                                          </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6899, 695, 133, '1', NULL, NULL, '<p>- The hatch coamings and stays are in saticfatory condition without any heavy corrosion was observed.</p><p> - The hatch covers found torn at various spot.</p><p> - The hatch cover could not be closed tightly and there was a gap about 14 cm between end of fore and aft of hatch cover.</p><p> - The some of rubber sealing/gasket found in normal condition and some not available.</p><p> - The condition of compession bar were in normal condition.</p><p> - The hatch cover protected and covered by 3 layer of tarpaulin sheet.rn                                                                                          </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6900, 695, 134, '4', NULL, NULL, 'No Ultrasonic leakage test was conducted, but hose test to hatch cover was carried out and found no leakage was observed.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6901, 695, 135, '1', NULL, NULL, '<p>- Internal structural members of ballast tank found to be in worn down paint coating and scaled, slightly corrosion at several places, but it visually still visually in good structural condition with zinc anodes fitted.</p><p>- The valve WBT Nos. 2P, 3P, 4P and 4S were not available and the blind flanged fitted.</p><p> - No marking on WBT vent and sounding pipe.rn                                                                                          </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6902, 695, 136, '1', NULL, NULL, 'Sounding pipe and tank top plate of WBT No. 1 centre found leakage.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6903, 695, 137, '4', NULL, NULL, '<p>- During our attendance in Engine Room, we found M/E is in satisfactory condition and free of oil leaks.</p><p> - We did running test of M/E and found running normally.rn                                                                                          </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6904, 695, 138, '4', NULL, NULL, '<p>- During our attendance in Engine Room, we found Emergency Generator was stored in steering gear room and in satisfactory condition and free of oil leaks.</p><p> - We did running test of Emergency Generator and found running normally.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6905, 695, 139, '4', NULL, NULL, '<p>- There were 4 (four) units of Auxialary Engine Nos. 1, 2, 3 (as also Emergency Generator) were stored in Engine Room, meawhile No. 4 on boat deck, and found the 4 (four) units of Auxialary Engine were in satisfactory condition and free of oil leaks.</p><p> - We did running test of all Auxialary Engines and found running normally.rn                                                                                          </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6906, 695, 140, '4', NULL, NULL, 'During our attendance, communication system between steering room and bridge is tested with satisfaction result.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6907, 695, 141, '4', NULL, NULL, 'During our attendance, we did test to emergency steering gear and found to be in satisfactory and running properly.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (6908, 669, 115, '2', NULL, NULL, 'Ultrasonic thickness measurement taken on 20 August 2025 until 30 August 2025. The diminution level of the vessel steel structures was still below the class maximum allowable limit of 20%', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
