INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7252, 728, 126, '6', NULL, NULL, 'The LCT vessel is not equipped with closed-type drainage holes. The deck drainage is designed to discharge directly overboard via side freeing ports. Consequently, the requirement for scupper plugs is not applicable to this vessel''s deck construction', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7253, 728, 127, '2', NULL, NULL, 'rn                                            A complete inventory of oil absorbent materials is available on board. All items are well-maintained and properly stowed within the SOPEP locker, in compliance with pollution prevention regulationsrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7254, 728, 129, '2', NULL, NULL, 'All decks / superstructure are in good condition. no structural damage or heavy rusting observed', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7255, 728, 130, '2', NULL, NULL, 'Watertight doors were inspected and found to be in normal condition, the opening and closing mechanism are smooth and the rubber seals are in good order', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7256, 728, 131, '6', NULL, NULL, 'The item ''Interior of Holds'' is Not Applicable (N/A) as this is an LCT-type vessel with an open deck design. The cargo is carried on the main deck, which was inspected and found to be in good structural condition with no significant damage or corrosionrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7257, 728, 132, '6', NULL, NULL, 'As an LCT, the vessel is designed with a flush open deck configuration without internal cargo holds. Consequently, there are no cargo bilge wells or associated suction piping systems installed. All deck drainage is naturally discharged overboard via freeing ports.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7258, 728, 133, '6', NULL, NULL, 'Due to the vessel''s LCT design, which features a continuous open deck for cargo stowage, no cargo hatch covers or associated sealing arrangements are installed. Maintenance of weather-tightness is focused on the manholes and small access hatches, which were found in good conditionrn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7259, 728, 134, '6', NULL, NULL, 'As the vessel is an LCT with no cargo hatch covers, ultrasonic or hose testing is not applicable.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7260, 728, 135, '2', NULL, NULL, 'Internal structure of ballast tanks shows no significant corrosion, thickness remain with normal limits and no cracks detected', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7261, 728, 136, '2', NULL, NULL, 'The Ballast Tank Pressure Test was conducted manually as the vessel is not equipped with remote ballast indicators. The test was performed by operating the ballast pumps and manually controlling the valves; all tanks maintained pressure without signs of leakage. System is functional despite the absence of automatic indicators.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7262, 728, 137, '2', NULL, NULL, 'the main engine is in good operational condition and functioning well', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
