INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7400, 694, 117, '1', NULL, NULL, 'rn                                            Deviation of magnetic compass found expire, last adjusted on January 31, 2023. rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
