INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7402, 694, 119, '1', NULL, NULL, '<p>rn                                            - Ship’s charts are in sufficient number and covering current vessel’s trading area.</p><p>- Ship’s charts were not update, last update in December 2015.<br>rn                                                                                                                                 </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7403, 694, 121, '1', NULL, NULL, 'Block diagram instruction for change procedures from auto tomanual steering and change of steering gear power units were notdisplayed on bridge.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7404, 694, 122, '1', NULL, NULL, 'SOPEP Locker was marked with “SOPEP” but without SOPEPEquipment like Oil absorbent pads/sorbent, Oil boom,Dispersant, Shovel, Bucket, Broom, PPE (Personal ProtectiveEquipment).<br>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7405, 694, 123, '1', NULL, NULL, 'rn                                            - Bunker connections/station is in fair condition and fitted with oil spill save-alls around bunker connection.<br>- The marking on bunkering connection must be painted.<br>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7406, 694, 124, '1', NULL, NULL, '<p>- Fuel air vents were in fair condition, no damage was observed. </p><p>- No proper marking on Fuel Air Vent </p><p>rn                                                                                         </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7407, 694, 125, '1', NULL, NULL, 'rn                                            - Save-alls bar plate on mooring winch and windlass on forward and aft found not available.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7408, 694, 126, '1', NULL, NULL, '- Scupper plugs were not available onboard. rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7409, 694, 127, '1', NULL, NULL, '- Oil Absorbents were not available on board. rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7410, 694, 128, '4', NULL, NULL, '- The port and starboard external side shell plating above the waterline found well coated.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7411, 694, 129, '1', NULL, NULL, 'rn                                            - Main Deck, forecastle and poop deck found in fair condition and well coated. <br>- Gutter bar plates on weather deck in starboard and portside were damaged and must be replated.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7412, 694, 130, '1', NULL, NULL, 'rn                                            - Water tight door’s rubber gasket on AC room and ACCU room were not available and must be installed.  <br>- Water tight entrance hatch’s rubber gasket on cargo hold hatchway were not available and must be installed. <br>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7413, 694, 131, '4', NULL, NULL, 'rn                                            - Inspection to cargo hold was carried out and found the steel structure of cargo hold was satisfactory. <br>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7414, 694, 132, '1', NULL, NULL, 'rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            rn                                            <p>- The hold’s bilge was found to contain residual water and remained previous cargo.</p><p>- The bilge water was disposed directly to sea. It is recommended to provide a designated bilge tank or convert unused ballast tanks into bilge tanks. Drums may be used as temporary storage.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7415, 694, 133, '1', NULL, NULL, 'rn                                            rn                                            <p>rn                                            - The hatch coamings and stays are in satisfactory condition without any heavy corrosion was observed.</p><p>- The hatch covers found holes at various spot.</p><p>- The hatch covers were not fitted with rubber sealing. Instead, they are guided by strip plates installed on the hatch coaming, allowing for drainage. The hatch covers are further protected by triple layers of tarpaulin. Opening and closing operations of the hatch covers are carried out using a crane. rn                                                                                                                                 </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7416, 694, 134, '4', NULL, NULL, '- No Ultrasonic leakage test was conducted, but hose test to hatchcover was carried out and found no leakage was observed. rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7417, 694, 135, '1', NULL, NULL, 'rn                                             -Internal structural of ballast tank was found to be fair conditions and installed with zinc anodes inside.<br>- All ballast valves were reportedly blind-flanged during the vessel’s conversion from a tanker to a general cargo ship. As a result, their locations could not be identified by the Chief Engineer, and it is likely that the pipelines were blanked off at the bulkhead during the conversion.<br>- No marking on WBT vent and sounding pipe.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7418, 694, 136, '1', NULL, NULL, 'rn                                            - Pressure test on ballast tank was conducted and found leakage on the man hole of ballast tank no. 2 and no. 10, the rubber man hole must be changed and the cement must be renewed regularly.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7419, 694, 137, '4', NULL, NULL, 'rn                                            - During our attendance in Engine Room, we found M/E is in good condition and free of oil leaks.- We did running test of M/E and found running normally.<br>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
