INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7518, 651, 28, '2', NULL, NULL, 'The mooring ropes/wires (including bridles) are in apparent good order.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7519, 652, 986, '2', NULL, NULL, 'The vessel’s hull was observed to be in generally fair condition. The shell plating appears intact with no visible signs of major structural deformation; however, localized corrosion, coating deterioration, and rust staining were noted along the waterline and side shell. Minor indentations and surface irregularities were also observed in several areas, likely due to operational wear and tear. Overall, while the hull remains serviceable, maintenance and recoating are recommended to prevent further deterioration.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7520, 652, 987, '1', NULL, NULL, 'In general, the condition of all decks and superstructure was found to be in good order at the time of inspection. However, it was noted that the port side forward bulwark was torn/damaged.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7521, 651, 29, '2', NULL, NULL, 'The mooring work areas are non-slippery and orderly.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7522, 652, 988, '2', NULL, NULL, 'Watertight openings, doors and ports were found to be in order.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7523, 652, 989, '2', NULL, NULL, 'Interior of hold was found to be in fair condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7524, 652, 990, '2', NULL, NULL, 'rn                                            Cargo hold bilge was found in order and suction test was carried out and found satisfactory.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7525, 652, 991, '1', NULL, NULL, 'rn                                            rn                                            rn                                            <p>The hatch covers are of folding type. The hatch cover plating was found in fair condition. The hatch cover was not close properly closed in fully shut position. During sailing, the hatch cover was covered with tarpaulins.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7526, 652, 997, '3', NULL, NULL, 'The vessel is equipped with 2 (two) auxiliary engines, which were found to be in good working order.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7527, 652, 999, '2', NULL, NULL, 'Emergency steering was tested. However, control remained from the bridge using manual wheel operation.  Local control from the steering heat room was not tested.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7528, 652, 998, '2', NULL, NULL, 'The bridge is equipped with 1 (one) marine VHF radio, 1 (one) handy talky, and 1 (one) telephone connected to the engine room.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7529, 651, 30, '2', NULL, NULL, 'The ballast tanks and void spaces were found to be free from significant wastage, pitting, and scale.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7530, 652, 995, '3', NULL, NULL, 'In good running condition, without any sign of significant leaking sighted.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7531, 652, 993, '2', NULL, NULL, '<p>At the time of our survey, we could inspect 4 (four) ballast tanks, which consist of Ballast tank No. 1P,  1S, 2S, and 2P.</p><p>The ballast tanks, complete with the internal structure, were found in fair condition.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7532, 652, 993, '2', NULL, NULL, '<p>At the time of our survey, we could inspect 4 (four) ballast tanks, which consist of Ballast tank No. 1P,  1S, 2S, and 2P.</p><p>The ballast tanks, complete with the internal structure, were found in fair condition.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7533, 651, 31, '2', NULL, NULL, 'The ballast tanks are fitted with a sufficient number of zinc anodes.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
