INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7613, 651, 40, '2', NULL, NULL, '<p>rn                                            The last maintenance of the Auxiliary Engines was conducted as follows:</p><p>AE 1 – January 2026, involving a top overhaul, including renewal of all injectors and replacement of the fuel injection (Bosch) pump. The maintenance was reported to have been carried out in accordance with the Engine Maker’s Manual.</p><p>AE 2 – December 2025, involving an overhaul of cylinder no. 4, including renewal of the liner, piston rings, piston, and crankpin bearing (metal jalan). The maintenance was reported to have been carried out in accordance with the Engine Maker’s Manual.rn                                                                                                                            </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
