INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7925, 773, 973, '4', NULL, NULL, 'The latest thickness measurements conducted on January 4, 2024, based on ultrasonic testing (UT), indicated that certain all bottom, side shell all main deck plating showed diminution ranging from 1.0% to 11.7% of the original thickness. However, overall, the results were generally satisfactory, with no widespread evidence of wastage exceeding 20% of the original plate thickness.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7926, 773, 973, '4', NULL, NULL, 'The latest thickness measurements conducted on January 4, 2024, based on ultrasonic testing (UT), indicated that certain all bottom, side shell all main deck plating showed diminution ranging from 1.0% to 11.7% of the original thickness. However, overall, the results were generally satisfactory, with no widespread evidence of wastage exceeding 20% of the original plate thickness.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
