INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7928, 773, 975, '1', NULL, NULL, '<ul><li>Gyro Compass is not function.</li><li>The vessel equiped with Magnetic Compas and in working order.</li><li>The vessel equiped with Furuno GPS Navigator Model GP-32 and in working order.</li><li>The vessel equiped with Garmin GPS Map 585 Plus and in working order.</li><li>Deviation of magnetic compas found expire, last adjusted on January 23, 2025.rn                                                                                                                               </li></ul>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
