INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7970, 773, 985, '1', NULL, NULL, 'Oil Absorbents are not available on board.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7971, 773, 986, '2', NULL, NULL, 'The port and starboard external side shell plating above the water line found in down paint coating, slightly rust, but it was still in fair condition.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7972, 773, 987, '1', NULL, NULL, '<ul><li>Main deck port and starboard side found rust and paint peel off at various spot.</li><li>Forecastle and poop deck found in good condition and good coated. No significant damage was observed on the pipe lines, bulkwarks, fairleads and other fittings on deck.</li></ul>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7973, 773, 988, '1', NULL, NULL, '<ul><li>Found no rubber seal at Bosun’s store watertight door.</li><li>Watertight door’s at port side and Engine Room are in good condition.</li></ul>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7974, 773, 989, '2', NULL, NULL, '<ul><li>Due to there were containers in cargo hold and on hatch cover, we could not inspected the cargo hold condition with freely.</li><li>We tried to inspect the internal structure of cargo hold as much as possible at port side, starboard side and aft, and noted that it was worn down paint coating, and slightly rust at several places but in fair structural condition.</li></ul>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7975, 773, 990, '1', NULL, NULL, '<ul><li>Hold’s bilge found remained of water.</li><li>During bilge suction test at port and starboard side using portable pump, noted that the water thrown directly into the sea.</li><li>For pump out the water in cargo hold bilge, the ship’s crew used portable pump with capacity of 22 m3/ hour.</li></ul>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7976, 773, 991, '1', NULL, NULL, '<ul><li>The hatch cover modify from single pull type to pontoon.</li><li>The hatch coaming stays found corrossion and torn at various places.</li><li>The hatch covers found corrossion and torn at various places.</li><li>There is a gap between each hatch cover. </li></ul>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7977, 773, 992, '1', NULL, NULL, 'rn                                            <ul><li>No Ultrasonic leakage test was conducted.</li><li>During hose test, the water inside into the cargo hold.</li></ul>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7978, 773, 993, '3', NULL, NULL, 'Internal structural members of ballast tank found to be in worn down paint coating and scaled, rust at several places, but it visually still visually in good structural condition.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7979, 773, 994, '1', NULL, NULL, '<ul><li>We did ballast pressure test to the ballast tank Nos. 2P/S, 3P/S and 4P/S.</li><li>During Ballast pressure test, found leakage on top plate of wing tank ballast No. 3 port side.</li><li>During Ballast pressure test, found leakage on top plate of wing tank ballast No. 4 port side.</li></ul>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7980, 773, 995, '4', NULL, NULL, '<ul><li>During our attendance in Engine Room, we found M/E is in satisfactory condition and free of oil leaks.</li><li>We did running test of M/E and found running normally.</li></ul>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7981, 773, 996, '4', NULL, NULL, '<ul><li>During our attendance in Bosun store room, we found Emergency Generator in satisfactory condition and free of oil leaks.</li><li>We did running test of Emergency Generator and found running normally.</li></ul>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7982, 773, 997, '4', NULL, NULL, '<ul><li>There were 3 (three) units of Auxialary Engine and 1 unit of generator connected with Main Engine, where’s A/E No. 1 and 1 unit of generator connected with M/E were store in Engine Room, A/E No. 2 was stored at Boat Deck, A/E No. 3 were store at Bosun Store Room. All the 3 (three) units of A/E and 1 (one) unit of Generator were in satisfactory condition and free of oil leaks.</li><li>We did running test of all Auxialary Engines and found running normally.</li></ul>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7983, 773, 998, '4', NULL, NULL, 'During our attendance, communication system between steering room and bridge is using Handy Talky and tested with satisfaction result.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7984, 773, 999, '4', NULL, NULL, 'During our attendance, we did test to emergency steering gear and found to be in satisfactory and running properly.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7985, 788, 22, '3', NULL, NULL, 'rn                                            Classification Certificate Valid and Updated until last inspection', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7986, 788, 114, '3', NULL, NULL, 'Certificate Competence of Officers valid and updated', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7987, 788, 115, '2', NULL, NULL, 'ultrasonic steel thickness measurement was not carried out during this inspection. the examination was limited to a visual inspection of the accessible structures. based on the visual inspection, the visible plating was found to be generally in satisfactory condition, with no apparent signs of deformation, significant damage, or exercise corrosion that could adversely affect the structural integrity. according to the available records, the vessel was last dry dock in 2023&nbsp;', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (7988, 788, 116, '2', NULL, NULL, 'Radar found in good and Functional condition', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
