INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8158, 516, 295, '1', NULL, NULL, '<p>rn                                            As far as we could ascertain, the sighted port side and starboard hull were found in fair condition, and the fair painting work with light indentation.</p><p><br>However, the forward starboard side shell was found cropped due to vessel maintenance at dry dock.<br>                                         </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8159, 516, 295, '1', NULL, NULL, '<p>rn                                            As far as we could ascertain, the sighted port side and starboard hull were found in fair condition, and the fair painting work with light indentation.</p><p><br>However, the forward starboard side shell was found cropped due to vessel maintenance at dry dock.<br>                                         </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8160, 516, 296, '1', NULL, NULL, 'rn                                            <p>The deck plating on the fore castle were found in fair condition; however, the doubling plates were fitted at several locations on the boat deck plating. </p><p>The coating was found not well-painted in several places due to the vessel maintenance at the dry dock.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8161, 516, 297, '1', NULL, NULL, 'The watertight doors were found not fitted with the rubber seal and were wastage at several places on the deck.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8162, 516, 298, '2', NULL, NULL, 'As far as we could ascertain, the cargo hold was generally found in fair condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8163, 516, 299, '1', NULL, NULL, 'The bilges at the cargo hold Nos 1 and 2 were found filled with water.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8164, 516, 300, '2', NULL, NULL, '<p>The hatch cover fitted on the vessel is a pontoon type that stacked on the hatch coaming. hence, compression bars, landing pads and securing devices are not applicable.</p><p>The hatch cover was covered by tarpaulins (3 layer) as a securing device.</p><p>rn                                                                                    </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8165, 516, 301, '6', NULL, NULL, 'Not applicable.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8166, 516, 302, '1', NULL, NULL, 'rn                                            <p>The steel structure and internal structure ballast tank Nos. 1P,1S,2P,2S,3P,3S are found wastage at several places. </p><p>The ballast tank Nos. 1P,1S,2P,2S,3P,3S were found without fitted with any zinc anodes.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8167, 516, 303, '5', NULL, NULL, 'The ballast tank pressure cannot be conducted while the vessel is placed in dry dock.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8168, 516, 303, '5', NULL, NULL, 'The ballast tank pressure cannot be conducted while the vessel is placed in dry dock.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8169, 516, 304, '5', NULL, NULL, 'The main engine was in good appearance, but the operation was not inspected while the vessel was placed in the dry dock.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8170, 516, 305, '5', NULL, NULL, '<p>The emergency generator was available onboard. </p><p>The vessel was fitted with 2 (two) emergency generators located on the 2nd deck and 3rd deck. </p><p>However, the emergency generator cannot be tested while the vessel placed at dry dock.rn                                                                                    </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8171, 516, 306, '5', NULL, NULL, 'rn                                            rn                                            <p>rn                                            The vessel was fitted with 2 (two) auxiliary engine and 2 (two) emergency generator. The auxiliary engine No. 1 & 2 is registered on the class certificate.</p><p><br>- 2 (two) engine of AE No.1 and AE No.2 is located in the engine room.<br>- 2 (two) engine of the emergency generator is located on the boat deck.</p><p><br>Based on the visual inspection and the engine logbook on the last voyage, the auxiliary engine was found in satisfactory condition with no abnormality sighted.</p><p><br>The auxiliary Engine No. 2 was undergoing routine maintenance at the time of the survey. </p><p>However,  we cannot tested the Auxiliary engines while the vessel is placed at dry dock.<br>rn                                                                                                                            </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8172, 516, 306, '5', NULL, NULL, 'rn                                            rn                                            <p>rn                                            The vessel was fitted with 2 (two) auxiliary engine and 2 (two) emergency generator. The auxiliary engine No. 1 & 2 is registered on the class certificate.</p><p><br>- 2 (two) engine of AE No.1 and AE No.2 is located in the engine room.<br>- 2 (two) engine of the emergency generator is located on the boat deck.</p><p><br>Based on the visual inspection and the engine logbook on the last voyage, the auxiliary engine was found in satisfactory condition with no abnormality sighted.</p><p><br>The auxiliary Engine No. 2 was undergoing routine maintenance at the time of the survey. </p><p>However,  we cannot tested the Auxiliary engines while the vessel is placed at dry dock.<br>rn                                                                                                                            </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8173, 516, 307, '2', NULL, NULL, 'The crew uses a telephone.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8174, 516, 308, '5', NULL, NULL, 'The emergency steering test was not conducted while the vessel placed at dry dock.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
