INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8532, 853, 22, '4', NULL, NULL, '<p>The certificates were not available on board at the time of our inspection, as they were reportedly under review by the Port Authority.</p><p>However, after the survey, the ship''s master provided us the ship''s certificatesand noted as follows:</p><p>Valid until : October 12, 2028</p><p>Last Inspection: october 22, 2025</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8533, 853, 114, '1', NULL, NULL, '<p>The certificates were not available on board at the time of our inspection, as they were reportedly under review by the Port Authority.</p><p>however, after the survey, the ship''s master provided the certificates of officers adn noted that the Deck officer such as Ship''s Master, Chief Officer, and Second Officer hold of ANT IV-M, meanwhile as per Minimum Safe Manning Document issued by the Directorate General of Sea Transportation on July 21, 2026, the minimum the Ship''s Master, Chief Officer, and Second Officer hold of ANT II. </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8534, 853, 115, '4', NULL, NULL, 'The latest thickness measurements conducted on October 19 up to november 15, 2023, based on ultrasonic testing (UT), showed diminution ranging from 0.1 mm to 2.10 mm of the original thickness. however, overall, the results were generally satisfactory, with no widespread evidence of wastage exceeding 20% of the original plate thickness.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8535, 853, 116, '1', NULL, NULL, 'The RADAR with ARPA Operational was not available on board, however RADAR itself was found to be in working order.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8536, 853, 117, '1', NULL, NULL, 'rn                                            <ul><li>Gyro Compass and Magnetic Compass in working condition.</li><li>Record of Magnetic Compass deviation was not available on board at the time of our inspection, however after the survey the ship''s master provided us with the Record of Magnetic Compas Deviation and noted that the last updated on November 24, 2023.</li></ul>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8537, 853, 118, '1', NULL, NULL, 'Last date of Berita Pelaut Indonesia''s (BPI) No. 22 was on May 29, 2026.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8538, 853, 119, '1', NULL, NULL, '<ul><li>Ship''s charts are in sufficient number and covering current vessel''s trading area.</li><li>the ship''s charts had not been updated to the latest available editions.</li></ul>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
