INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8541, 853, 122, '1', NULL, NULL, 'The SOPEP box contained sawdust in bags only, without equipments and tools such as shovels, broms, caption rags, sand, absorbent material, oil spill dispersent (OSD), absorbent pads oil, liquid detergent, bailer, bucket, wilden pump with hoses, nozzle sprayer adn rubber suits, boots and gloves.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
