INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8553, 853, 134, '3', NULL, NULL, 'No Ultrasonic leakage test was conducted. however, a hose test was carried out on the hatch covers, and no signs of water leakage were observed during the test.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8554, 853, 133, '3', NULL, NULL, '<ul><li>The hatch coamings and stays are in good condition without any heavy corrosion was observed.</li><li>The hatch covers found in good condition, no significant damage was observed.</li><li>The rubber sealing/gasket found in normal condition.</li><li>the condition of compression bar were in normal condition.</li><li>The hatch cover protected and covered by 1 layer of tarpaulin sheet.</li></ul>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8555, 853, 135, '2', NULL, NULL, 'Internal structural members of ballast tank found to be in worn down paint coating and scaled, slightly corrossion at several places, and still remain of water, but it visually still in good structural condition.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8556, 853, 136, '4', NULL, NULL, 'We were carried out pressure test to the ballast tanks Nos. 1-4 P/S and found no leakage.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8557, 853, 137, '4', NULL, NULL, 'rn                                            <ul><li>During our inspection, the Main Engine (M/E) was found to be in satisfactory condition with no signs of oil leakage observed.</li><li>We did running test of M/E and found running normally.</li></ul>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8558, 853, 138, '4', NULL, NULL, '<ul><li>During our inspection, we found the Emergency Generator stored in engine room and to be in satisfactory condition with no signs of oil leakage observed.</li><li>We did running test of Emergency Generator and found running normally.</li></ul>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8559, 853, 139, '4', NULL, NULL, 'rn                                            <ul><li>There were 4 (four) units of Auxialary Engine Nos. 1, 2, and 3 were stored in Engine Room, and 1 (one) unit of Auxialary Engine was stored at boat deck., and found in satisfactory condition and with no signs of oil leakage observed.</li><li>We did running test of all Auxialary Engines and found running normally.</li></ul>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8560, 853, 140, '4', NULL, NULL, 'rn                                            During our attendance, communication system between steering room and bridge used telephone and handy talky, and tested with satisfaction result.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
