INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8578, 943, 37, '2', NULL, NULL, 'rn                                            <p>THE LAST MAINTENANCE OF THE MAIN ENGINE WAS CONDUCTED IN FEBRUARY 11, 2026 UNTIL MARCH 12, 2026. </p><p>INVOLVING A TOP OVERHAUL WITH CALIBRATION FUEL INJECTION PUMP, CALIBRATION GOVERNOR, CYLINDER NO 6 (LINER + PISTON + HEAD CYLINDER + ALL RING PISTON) </p><p>THE MAINTENANCE WAS REPORTED TO HAVE BEEN CARRIED OUT IN ACCORDANCE WITH THE ENGINE MAKER MANUAL </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8579, 943, 41, '2', NULL, NULL, 'THE CONDITION OF AUXILIARY ENGINE ARE GOOD CONDITION AND WORKING PROPERLY', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
