INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8822, 905, 124, '1', NULL, NULL, '<p>rn                                            - Fuel air vents in fair condition, no damage was observed.</p><p>- The marking on Fuel Air Vents must be painted.</p><p>- The wire mesh is missing and must be replaced.</p><p>- Cover of fuel air vent was missing and must be replaced.<br>rn                                                                                                                            </p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
