INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8828, 905, 130, '1', NULL, NULL, '- Water tight rubber gaskets were found in fair condition.- The marking on the several water tight doors must berepainted. <br>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8829, 905, 131, '4', NULL, NULL, '- Inspection to cargo hold was carried out and found the steelstructure of cargo hold was satisfactory. <br>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8830, 905, 132, '4', NULL, NULL, 'rn                                            - Hold’s bilge found remained of water and had been sucked and cleaned. <br>- The bilge water suction operation was carried out manually due to small water inside the hold’s bilge. It was informed that the suction was normally conducted by submersible pump and the waters were collected into the drums.<br>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8831, 905, 133, '4', NULL, NULL, 'rn                                            rn                                            - The hatch coamings and stays are in satisfactory condition without any heavy corrosion was observed.<br>- The hatch covers were not fitted with rubber sealing. Instead, they are guided by strip plates installed on the hatch coaming, allowing for drainage. The hatch covers are further protected by triple layers of tarpaulin. Opening and closing operations of the hatch covers are carried out using a crane.<br>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8832, 905, 134, '1', NULL, NULL, '- The hose test was carried out and found 2 spots leaking to thecargo hold. The terpaulin must be renewed regularly to avoidwater leakage.<br>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8833, 905, 135, '5', NULL, NULL, '- All ballast tanks were full of water during the empty hold andthe ballast water was to be discharged and will be removedonce berthing at the port. Accordingly, an internal inspectionof the ballast tank structures could not be carried out at thetime of our inspection. <br>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8834, 905, 136, '4', NULL, NULL, 'rn                                            - Pressure test on entire ballast tanks was conducted and no leakage found.<br>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8835, 905, 137, '4', NULL, NULL, '- During our attendance in Engine Room, we found M/E is ingood condition and free of oil leaks.<br>- We did running test of M/E and found running normally.<br>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8836, 905, 138, '4', NULL, NULL, '- During our attendance, we found Emergency Generators werestored in boat deck and in good condition and free of oil leaks.<br>- We did running test of Emergency Generator and foundrunning normally.<br>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8837, 905, 139, '4', NULL, NULL, '- There were 2 (two) units of Auxiliary Engine Nos. 1 and 2were stored in Engine Room and found the 2 (two) units ofAuxiliary Engine were in good condition and free of oil leaks.<br>- We did running test of all Auxiliary Engines and foundrunning normally.<br>rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
