INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8993, 944, 129, '1', NULL, NULL, 'CONDITION OF ALL DECKS IS IN CRITICAL CONDITION WITH EXTENSIVE CORROSION,. <br>SEVERE CORROSION IS PRESENT ON BOTH THE PORT AND THE STARBOARD SIDES OF THE MAIN DECK. BOTH THE PORT AND STARBOARD BULLWARKS ARE HEAVILY CORRODED, WITH SEVERAL CRACKS OBSERVED. HEAVY CORROSION IS ALSO FOUND IN THE BOW AREA. THE BOLLARDS ARE NON-FUNCTIONAL, AND THE STARBOARD WINCH MOTOR IS MISSING FROM THE VESSEL DUE TO ONGOING REPAIRS. THE BOW RAILINGS ARE BENT, MISSING, AND THE CORRODED, WHILE THE DECK WATER PIPES SHOW SEVERE CORROSION. THE ACCOMMODATION LADDER FROM MAIN DECK IS SEVERLEY RUSTED WITH SEVERAL CRACKED AND BROKEN PLATES. THE MAIN DECK AT THE STERN SUFFERS FROM SEVERE CORROSION, FEATURING HOLES, HEAVY CORROSION AND THE THINNED PLATING ON THE DECK FLOOR. THE AFT BOLLARD IS ALSO NON-FUNCTIONAL. ON BOTH PORT AND STARBOARD BRIDGE WINGS, THE DECK FLOORING SHOW HEAVY CORROSION, ALONG WITH SEVERAL BROKEN AND BENT RAILINGS', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8994, 944, 130, '2', NULL, NULL, 'THE WATERTIGHT DOORS WERE FOUND IN GOOD CONDITION, MECHANISM MOVE FREELY, AND RUBBER SEALS ARE INTACT', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8995, 919, 56, '2', NULL, NULL, 'The pipes were painted in different colors according to the applicable color code.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8996, 944, 131, '1', NULL, NULL, 'INTERIOR OF CARGO HOLDS WERE FOUND INSIDE THE CARGO HOLD, SEVERAL THIN PLATES AND CRACKS WERE OBSERVED ON THE UPPER SECTION OF THE STARBOARD BULKHEAD', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8997, 944, 132, '2', NULL, NULL, 'CARGO HOLD BILGE CLEANLINESS WERE FOUND A LITTLE BIT HAVE WATER IN THE CARGO HOLD BILGE AND THE SUCTION TEST WASS CARRIED OUT AND SATISFACTORY', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8998, 944, 133, '1', NULL, NULL, 'THERE IS CORROSION ON SEVERAL PARTS OF THE HATCH COVERS. ADDITIONALLY, CRACKED PLATES ND CRACKED RUBBER SEALS WERE FOUND IN MULTIPLE AREAS, AND SOME SECTIONS OF THE HATCH COVERS ARE MISSING THEIR RUBBER SEALS COMPLETELY', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (8999, 944, 134, '2', NULL, NULL, 'rn                                            rn                                            HOSE TEST WAS CARRIED OUT', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9000, 944, 135, '1', NULL, NULL, 'rn                                            THERE IS MODERATE TO HEAVY CORROSION INSIDE BALLAST TANKS NO. 3 AND NO. 4 (BOTH PORT AND STARBOARD). SEVERAL STRUCTURAL MEMBERS (FRAMES) SHOW SIGNS OF HEAVY RUST SCALING, AND THE COATING/PAINT SYSTEM INSIDE THE TANKS HAS SUFFERED DAMAGE. BUT THE BALLAST TANKS NO. 1, NO. 2, AND NO. 5 CAN''T INSPECTED BECAUSE THE BALLAST TANKS HAVE WATER', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9001, 944, 136, '2', NULL, NULL, 'BALLAST TANKS PRESSURE TEST WAS CARRIED OUT AND THE RESULT SATISFACTORY', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9002, 944, 137, '2', NULL, NULL, 'THE MAIN ENGINE WAS FOUND IN GOOD CONDITION AND WORKING PROPERLY - YES, THE ENGINE TRUSTWORTHY', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9003, 944, 138, '1', NULL, NULL, 'EMERGENCY GENERATOR WAS FOUND STILL UNDER REPAIR. THE LOCATION IN THE ENGINE ROOM', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
