INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9320, 851, 138, '2', NULL, NULL, 'The emergency generator was located on the second deck and was found to be in good working order when tested.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9321, 851, 139, '2', NULL, NULL, 'The auxiliary engine was found in good working order.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9322, 851, 140, '2', NULL, NULL, 'Communication with the bridge was maintained using portable VHF radio (handheld radio).', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9323, 851, 141, '2', NULL, NULL, 'The emergency steering test was found to be in order when tested.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
