INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9326, 851, 134, '2', NULL, NULL, 'A hose test was carried out on the hatch covers,, and the results were found to be satisfactory.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9327, 970, 22, '2', NULL, NULL, '<span xss=removed>Hull, Engine, and Load Line Class Certificate was available on board and was valid until 23 September 2030. Last inspection 10 December 2025.</span>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
