INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9329, 970, 115, '2', NULL, NULL, 'rn                                                                                     <span xss=removed>The UTM Report was available onboard. The measured steel thickness diminution was found to be below the Class maximum allowable limit of 20%. Any areas exceeding the allowable limit will be repaired or renewed in accordance with the Class requirements.</span>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
