INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9350, 970, 129, '2', NULL, NULL, '<span xss=removed>The overall condition of the deck and superstructure was found to be fair.</span>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9351, 970, 130, '1', NULL, NULL, 'The watertight doors and hatches to the cargo hold were found with partially missing rubber gasket.', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9352, 970, 131, '1', NULL, NULL, 'rn                                            <p>Doubling Plate was found between cargo hold No. 2 and the engine room.</p><p>Doubling Plate was found on the tween deck of cargo hold No. 1.</p><p>Small holes were found on the tween deck and the stiffeners of cargo hold No. 1.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9353, 970, 132, '2', NULL, NULL, '<span xss=removed>The suction test of cargo hold bilge was found in order.</span>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9354, 970, 133, '2', NULL, NULL, 'The cargo hold was fitted with concrete hatch covers, which were removable by crane and covered with four (4) layers of tarpaulin.rn', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9355, 970, 134, '6', NULL, NULL, '<span xss=removed>Not applicable by ship design.</span>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9356, 970, 135, '1', NULL, NULL, '<p>Ballast tanks No. 1P, 1S, 2P, and 2S were found generally corroded with wastages at several places.</p><p>The zinc anode in ballast tank No. 1P and 2P were found substantially consumed.</p>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9357, 970, 136, '1', NULL, NULL, 'During the ballast tanks pressure test, leakage was found in the cargo hold No. 1 (on the inner bottom plate and the air vent pipe of ballast No. 1P)', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9358, 970, 137, '2', NULL, NULL, '<span xss=removed>General condition of main engine was found in good condition.</span>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9359, 970, 138, '2', NULL, NULL, '<span xss=removed>The general condition of the 2 (two) emergency generators on the boat deck was found to be in good condition and found in order.</span>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
INSERT INTO survey_responses (response_id, survey_id, item_id, response, risk_impact, risk_rating, remarks_from_surveyor, created_at, updated_at) VALUES (9360, 970, 139, '2', NULL, NULL, '<span xss=removed>All auxiliary engine were found in good condition and in order.</span>', NOW(), NOW()) ON CONFLICT (response_id) DO NOTHING;
