INSERT INTO log_rectification (id, id_deffect, value, category, datetime, id_admin, created_at, updated_at) VALUES (183, 150, 'The damage to the plate is a result of the cargo. The steel was installed to prevent the cargo from coming into contact with the cargo hold wall. It should be noted that the steel is still of a considerable thickness, despite the shipowner renewing the plate. It is likely that the steel will become dented again due to the cargo.', 'rectification_owner', '2024-09-03 08:19:31', 4, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO log_rectification (id, id_deffect, value, category, datetime, id_admin, created_at, updated_at) VALUES (184, 150, 'The dented to the plate is a result of the cargo. The steel was installed to prevent the cargo from coming into contact with the cargo hold wall. It should be noted that the steel is still of a considerable thickness, despite the shipowner renewing the plate. It is likely that the steel will become dented again due to the cargo.', 'rectification_owner', '2024-09-03 08:23:52', 4, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
