INSERT INTO log_rectification (id, id_deffect, value, category, datetime, id_admin, created_at, updated_at) VALUES (973, 376, 'Refer to the latest UT report which we find it in ANUGERAH VIII survey report''s attachment, we are in the opinion that the plate thickness of the vessel and the reduction in plate thickness of the ANUGERAH VIII vessel are still within normal and reasonable limits.', 'rectification_owner', '2025-11-05 02:47:55', 4, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO log_rectification (id, id_deffect, value, category, datetime, id_admin, created_at, updated_at) VALUES (974, 423, 'Decline - Based on the photographs provided by the owners,  it is not the scupper plugs. Therefore, the scupper plugs are to be provided onboard.', 'status_remark', '2025-11-05 03:02:18', 21, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
