INSERT INTO log_rectification (id, id_deffect, value, category, datetime, id_admin, created_at, updated_at) VALUES (1252, 705, 'Approve - Deficiency rectified; radar logbook entries are now being maintained. The Master and crew must ensure consistent and diligent record-keeping for all future operations.', 'status_remark', '2026-01-19 08:06:50', 88, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO log_rectification (id, id_deffect, value, category, datetime, id_admin, created_at, updated_at) VALUES (1253, 697, 'Approve - Based on the photos provided, oil absorbents have been partially supplied. The Master must ensure the remaining items are promptly provided on board and maintenance checks are strictly observed to maintain emergency readiness.', 'status_remark', '2026-01-19 08:14:45', 88, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO log_rectification (id, id_deffect, value, category, datetime, id_admin, created_at, updated_at) VALUES (1254, 706, 'Approve - Rectification of deck items verified via photographic evidence. It is recommended that the crew maintains a strict preventive maintenance schedule to ensure the vessel remains in good condition', 'status_remark', '2026-01-19 08:16:39', 88, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO log_rectification (id, id_deffect, value, category, datetime, id_admin, created_at, updated_at) VALUES (1255, 699, 'Approve - Watertight door rubber seals have been replaced and verified via photos. The Master must ensure that seals are kept clean and regularly greased to maintain the vessel''s water-tight integrity', 'status_remark', '2026-01-19 08:18:15', 88, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO log_rectification (id, id_deffect, value, category, datetime, id_admin, created_at, updated_at) VALUES (1256, 700, 'Approve - Based on photo and video provided, the defective ballast tank pressure gauge has been repaired and is now fully operational. Regular calibration and routine checks must be strictly observed to ensure accurate monitoring of tank pressure', 'status_remark', '2026-01-19 08:20:25', 88, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO log_rectification (id, id_deffect, value, category, datetime, id_admin, created_at, updated_at) VALUES (1257, 703, 'Approve - Evidence of logbook entries for emergency steering test provided via photos. Deficiency rectified; emergency steering tests are now being recorded in the logbook. The Master must ensure that these tests are carried out and documented at regular intervals to comply with SOLAS requirements and ensure emergency readiness.', 'status_remark', '2026-01-19 08:22:47', 88, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
